#!/usr/bin/env bash
# =============================================================================
#  Pingify - point-to-point tunnel manager for Iran <-> Kharej server pairs
#  https://github.com/GreatTeejay/Pingify
#
#  This file is generated by build.sh: it bundles the manager and the whole Go
#  core source, so a single file is everything either server needs.
#  Edit parts/*.sh and the Go tree, then run build.sh - never edit Pingify.sh.
# =============================================================================

set -o pipefail

PINGIFY_VERSION="1.0.1"
PINGIFY_REPO="${PINGIFY_REPO:-GreatTeejay/Pingify}"

# ---------------------------------------------------------------------------
# what this terminal can do
#
# Colour only when somebody is looking. Box drawing degrades to ASCII on a
# console that is not talking UTF-8, so a bare serial session still renders
# something sane. The width follows the window, between 40 and 120 columns,
# and the frames stop at 68 however wide the window is: a box pulled across a
# two hundred column terminal is a box the eye cannot follow.
# ---------------------------------------------------------------------------

ui_detect() {
    UI_COLOR=8
    UI_GLYPH=ascii
    case "${TERM:-dumb}" in dumb | "") UI_COLOR=none ;; esac
    [ -n "${NO_COLOR:-}" ] && UI_COLOR=none
    [ -t 1 ] || UI_COLOR=none
    if [ "$UI_COLOR" != none ] && [ "$(tput colors 2>/dev/null || echo 0)" -ge 256 ]; then
        UI_COLOR=256
    fi
    case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *[Uu][Tt][Ff]*) UI_GLYPH=utf8 ;;
    esac
    [ -n "${PINGIFY_ASCII:-}" ] && UI_GLYPH=ascii
    # A locale that names UTF-8 but is not installed - LANG carried over ssh
    # from a laptop to a server that never generated it - leaves bash
    # counting bytes, so every box drawn with glyphs comes out shredded.
    # If this shell cannot see one glyph as one character, draw in ASCII.
    # Every measurement of text below is made under a UTF-8 character type
    # that this bash can actually use: the session's own if it works, one of
    # the two every server has otherwise. With none, the glyphs are ASCII.
    UI_CTYPE=
    local l
    for l in "${LC_ALL:-}" "${LC_CTYPE:-}" "${LANG:-}" C.UTF-8 C.utf8 en_US.UTF-8; do
        [ -n "$l" ] || continue
        ui_mb_ok "$l" 2>/dev/null && { UI_CTYPE=$l; break; }
    done
    [ -n "$UI_CTYPE" ] || UI_GLYPH=ascii
    PINGIFY_UTF8=0
    [ "$UI_GLYPH" = utf8 ] && PINGIFY_UTF8=1

    UI_TERM=${PINGIFY_WIDTH:-$(tput cols 2>/dev/null || echo 80)}
    case "$UI_TERM" in '' | *[!0-9]*) UI_TERM=80 ;; esac
    [ "$UI_TERM" -gt 120 ] && UI_TERM=120
    [ "$UI_TERM" -lt 40 ] && UI_TERM=40
    UI_W=$UI_TERM
    [ "$UI_W" -gt 68 ] && UI_W=68

    ui_palette
    ui_glyphs
}

# ui_mb_ok says whether bash sees one glyph as one character under a locale.
ui_mb_ok() {
    local LC_ALL=$1 probe='─'
    [ "${#probe}" = 1 ]
}

ui_palette() {
    if [ "$UI_COLOR" = none ]; then
        C_OFF= C_B= C_DIM= C_RED= C_GRN= C_YEL= C_BLU= C_MAG= C_CYN= C_GRY=
    else
        C_OFF=$'\033[0m' C_B=$'\033[1m' C_DIM=$'\033[2m'
        C_RED=$'\033[31m' C_GRN=$'\033[32m' C_YEL=$'\033[33m'
        C_BLU=$'\033[34m' C_MAG=$'\033[35m' C_CYN=$'\033[36m'
        C_GRY=$'\033[90m'
        # Raw cyan is unreadable on a white terminal; with 256 colours the
        # accent is a desaturated teal instead.
        [ "$UI_COLOR" = 256 ] && C_CYN=$'\033[38;5;37m'
    fi
    # The same colours by the role they play, which is how the screens that
    # report on a tunnel name them.
    C_ACCENT=$C_CYN C_OK=$C_GRN C_WARN=$C_YEL C_BAD=$C_RED
    C_MUTE=$C_GRY C_KEY=$C_DIM C_RULE=$C_GRY C_ADDR=$C_CYN
}

ui_glyphs() {
    if [ "$UI_GLYPH" = utf8 ]; then
        BX_H='─' BX_V='│' BX_TL='╭' BX_TR='╮' BX_BL='╰' BX_BR='╯'
        BX_DOT='·' BX_ARR='▸' BX_ON='●' BX_OFF='○'
        MK_OK='✓' MK_NO='✗' MK_WARN='!'
        G_ARROW='→' G_BOTH='⇄' G_CUT='…' G_DASH='—'
    else
        BX_H='-' BX_V='|' BX_TL='+' BX_TR='+' BX_BL='+' BX_BR='+'
        BX_DOT='.' BX_ARR='>' BX_ON='*' BX_OFF='o'
        MK_OK='+' MK_NO='x' MK_WARN='!'
        G_ARROW='->' G_BOTH='<->' G_CUT='~' G_DASH='-'
    fi
    G_H=$BX_H G_V=$BX_V G_TL=$BX_TL G_TR=$BX_TR G_BL=$BX_BL G_BR=$BX_BR
    G_CUR=$BX_ARR G_ITEM=$BX_ARR G_DOT=$BX_DOT G_ON=$BX_ON G_OFF=$BX_OFF
    G_OK=$MK_OK G_BAD=$MK_NO G_WARN=$MK_WARN
}

# ---------------------------------------------------------------------------
# measuring and cutting text
# ---------------------------------------------------------------------------

rep() {
    local out
    [ "${2:-0}" -gt 0 ] 2>/dev/null || return 0
    printf -v out '%*s' "$2" ''
    printf '%s' "${out// /$1}"
}

# vislen is how many columns a string occupies once the escape codes are
# gone. Columns, not characters: a CJK glyph is two and a combining mark is
# none. Parameter expansion rather than sed, because this runs once per cell
# and a subprocess per cell is how a menu comes to take a second over ssh.
vislen() {
    local LC_ALL=${UI_CTYPE:-C} s=$1 out= n i ch cp
    while [ -n "$s" ]; do
        case $s in
        $'['*)
            s=${s#$'['}
            s=${s#*m}
            continue
            ;;
        esac
        out=$out${s:0:1}
        s=${s:1}
    done
    n=${#out}
    # Bash counts characters; correct for the ones that are not one column.
    # By code point rather than by a bracket range: in en_US.UTF-8 a range
    # is collated, not ordered, and a box-drawing glyph fell inside the CJK
    # range on a server abroad, so every frame there came out shredded.
    for ((i = 0; i < ${#out}; i++)); do
        ch=${out:i:1}
        printf -v cp '%d' "'$ch" 2>/dev/null || cp=0
        [ "$cp" -lt 768 ] && continue
        if ((cp <= 879 || (cp >= 1611 && cp <= 1631) || (cp >= 8204 && cp <= 8207))); then
            n=$((n - 1))
        elif (((cp >= 4352 && cp <= 4447) || (cp >= 11904 && cp <= 42191) || (cp >= 44032 && cp <= 55203) ||
            (cp >= 63744 && cp <= 64255) || (cp >= 65072 && cp <= 65103) || (cp >= 65280 && cp <= 65376) ||
            (cp >= 65504 && cp <= 65510) || (cp >= 127744 && cp <= 129791))); then
            n=$((n + 1))
        fi
    done
    printf '%s' "$n"
}

# trunc_to cuts a string to a width and marks that it did. A value that does
# not fit and is printed anyway takes the next column's place.
# trunc_to STRING WIDTH - the string cut to fit, with the cut marked. Colour
# codes are carried through and never counted, and a cut string always ends
# with the colour reset so what was bold or dim does not run on into the
# next line.
trunc_to() {
    local LC_ALL=${UI_CTYPE:-C} s=$1 w=$2 cut out= n=0 seen=0
    [ "$(vislen "$s")" -le "$w" ] && { printf '%s' "$s"; return; }
    cut=$((w - 1))
    [ "$cut" -lt 1 ] && cut=1
    while [ -n "$s" ] && [ "$n" -lt "$cut" ]; do
        case $s in
        $'\033['*)
            out=$out${s%%m*}m
            s=${s#*m}
            seen=1
            continue
            ;;
        esac
        out=$out${s:0:1}
        s=${s:1}
        n=$((n + 1))
    done
    [ "$seen" = 1 ] && out=$out$C_OFF
    printf '%s%s' "$out" "$G_CUT"
}

pad_to() {
    local s n
    s=$(trunc_to "$1" "$2")
    n=$(vislen "$s")
    printf '%s%*s' "$s" "$(($2 - n))" ''
}

# ---------------------------------------------------------------------------
# colour with a meaning
#
# An address is the thing people copy, compare and mistype, so it gets a
# colour of its own. A round trip is banded where an Iran <-> abroad path
# changes character: under 100 ms is a nearby datacentre behaving, 100-200
# is usable but felt, over 200 is a long way round or a path in trouble. A
# thing that cannot be measured is grey, never red: red means "this path is
# slow", not "there is no path".
# ---------------------------------------------------------------------------

addr_tint() { printf '%s%s%s' "$C_ADDR" "$1" "$C_OFF"; }

rtt_colour() {
    local ms=${1%ms}
    ms=${ms%%.*}
    case $ms in '' | *[!0-9]*) printf '%s' "$C_MUTE"; return ;; esac
    if [ "$ms" -lt 100 ]; then printf '%s' "$C_OK"
    elif [ "$ms" -lt 200 ]; then printf '%s' "$C_WARN"
    else printf '%s' "$C_BAD"; fi
}
rtt_tint() { printf '%s%s%s' "$(rtt_colour "$1")" "$1" "$C_OFF"; }

# ---------------------------------------------------------------------------
# drawing primitives
# ---------------------------------------------------------------------------

# fill_to writes a line and fills the rest of the width with a glyph, so
# every rule and every box edge is measured rather than counted.
fill_to() {
    local text=$1 glyph=$2 tail=${3:-} n
    n=$((UI_W - $(vislen "$text") - $(vislen "$tail")))
    [ "$n" -lt 0 ] && n=0
    printf '%s%s%s%s%s' "$text" "$C_RULE" "$(rep "$glyph" "$n")" "$tail" "$C_OFF"
}

# A panel carries its title in the top border, so a screen full of them reads
# as a list of labelled blocks rather than a wall of rules.
panel() {
    if [ -z "${1:-}" ]; then
        printf '%s\n' "$(fill_to "  $C_RULE$BX_TL" "$BX_H" "$BX_TR")"
        return
    fi
    printf '%s\n' "$(fill_to "  $C_RULE$BX_TL$BX_H$C_OFF $C_CYN$C_B$1$C_OFF " "$BX_H" "$BX_TR")"
}
panel_open() { panel "$1"; }
panel_end() { printf '%s\n' "$(fill_to "  $C_RULE$BX_BL" "$BX_H" "$BX_BR")"; }
panel_close() { panel_end; }

# One line inside a box, cut to fit: a value that overran pushed the closing
# bar off the end and shredded the panel.
panel_row() {
    local inner=$((UI_W - 6))
    printf '  %s%s%s %s %s%s%s\n' \
        "$C_RULE" "$BX_V" "$C_OFF" "$(pad_to "$1" "$inner")" "$C_RULE" "$BX_V" "$C_OFF"
}

# panel_field <label> <value> [label2] [value2] - a boxed key and value, two
# aligned columns in one row when a second pair is given.
UI_PANELW=13
panel_field() {
    local s inner=$((UI_W - 6))
    s="$(pad_to "${C_DIM}$1${C_OFF}" "$UI_PANELW")  ${C_B}$2${C_OFF}"
    if [ -n "${3:-}" ]; then
        # Two pairs share a row only when the row has room for both; below
        # that the second pair takes a row of its own rather than a letter.
        if [ "$inner" -ge 56 ]; then
            s="$(pad_to "$s" $((inner / 2)))$(pad_to "${C_DIM}$3${C_OFF}" $((UI_PANELW - 2))) ${C_B}$4${C_OFF}"
        else
            panel_row "$s"
            s="$(pad_to "${C_DIM}$3${C_OFF}" "$UI_PANELW")  ${C_B}$4${C_OFF}"
        fi
    fi
    panel_row "$s"
}

# field is the same pair on a plain screen, outside any box.
UI_KEYW=11
field() {
    printf '    %s%s%s  %s\n' \
        "$C_KEY" "$(pad_to "$1" "$UI_KEYW")" "$C_OFF" \
        "$(trunc_to "$2" $((UI_W - UI_KEYW - 8)))"
}

# row prints cells padded to the widths in UI_COLS, which the caller sets
# once, so a header and its rows cannot drift apart.
row() {
    local i=0 out= cell
    for cell in "$@"; do
        out=$out$(pad_to "$cell" "${UI_COLS[i]:-12}")'  '
        i=$((i + 1))
    done
    out=${out%  }
    printf '   %s\n' "$(trunc_to "$out" $((UI_TERM - 3)))"
}

say()  { printf '%s\n' "$*"; }
blank() { printf '\n'; }
info() { say_wrapped "  ${C_CYN}${BX_ARR}${C_OFF} " "    " "$*"; }
ok()   { say_wrapped "  ${C_GRN}${MK_OK}${C_OFF} " "    " "$*"; }
warn() { say_wrapped "  ${C_YEL}${MK_WARN}${C_OFF} " "    " "$*"; }
fail() { say_wrapped "  ${C_RED}${MK_NO}${C_OFF} " "    " "$*"; }
bad()  { fail "$@"; }
# fold WIDTH TEXT - the text broken on spaces so that no line is wider than
# WIDTH. Colour codes are carried through and not counted, so a coloured
# word does not make a short line look long.
fold() {
    local w=$1 word line= out=
    for word in $2; do
        if [ -z "$line" ]; then
            line=$word
        elif [ "$(vislen "$line $word")" -le "$w" ]; then
            line="$line $word"
        else
            out="$out$line
"
            line=$word
        fi
    done
    printf '%s' "$out$line"
}

# say_wrapped PREFIX INDENT TEXT - one of the lines below, folded at the
# screen's width. A sentence used to run off the right edge of an eighty
# column terminal, and a wrapped fix line lost its indent, which read as a
# second item.
say_wrapped() {
    local prefix=$1 pad=$2 text=$3 first=1 line
    while IFS= read -r line; do
        if [ "$first" = 1 ]; then
            printf '%s%s
' "$prefix" "$line"
            first=0
        else
            printf '%s%s
' "$pad" "$line"
        fi
    done <<<"$(fold $((UI_W - ${#pad})) "$text")"
}

dim()  { say_wrapped "    ${C_DIM}" "    " "$*${C_OFF}"; }
# dim_wrap LEAD SEP - dim lines from the items on standard input, one an
# item, folded at the screen's width. LEAD opens the first line and its
# width indents the rest, so a list that would run off the right edge folds
# under itself. SEP goes between items; its first word ends a folded line,
# so a comma list folds with a comma.
dim_wrap() {
    local lead=$1 sep=$2 w=$((UI_W - 4)) lw pad line cur n=0 item tail
    lw=$(vislen "$lead")
    pad=$(printf '%*s' "$lw" '')
    tail=${sep%%[[:space:]]*}
    line=$lead cur=$lw
    while IFS= read -r item; do
        [ -n "$item" ] || continue
        if [ "$n" -gt 0 ] && [ $((cur + ${#sep} + ${#item})) -gt "$w" ]; then
            dim "$line$tail"
            line="$pad$item" cur=$((lw + ${#item})) n=1
        elif [ "$n" -gt 0 ]; then
            line="$line$sep$item" cur=$((cur + ${#sep} + ${#item})) n=$((n + 1))
        else
            line="$line$item" cur=$((cur + ${#item})) n=1
        fi
    done
    [ "$n" -gt 0 ] && dim "$line"
    return 0
}
# fix is the line under a failure that says what to do about it.
fix()  { say_wrapped "      ${C_CYN}${BX_ARR} fix:${C_OFF} " "           " "$*"; }
die()  { printf '\n  %s%s%s %s\n\n' "$C_RED" "$MK_NO" "$C_OFF" "$*" >&2; exit 1; }

# rule draws a horizontal line, with a title inside it when given one.
rule() {
    if [ -z "${1:-}" ]; then
        printf '  %s%s%s\n' "$C_GRY" "$(rep "$BX_H" "$UI_W")" "$C_OFF"
        return
    fi
    head2 "$1"
}

# A section heading whose rule runs out to the panel width.
head2() {
    local t=" $1 " n
    n=$(vislen "$t")
    printf '\n  %s%s%s%s%s%s%s\n\n' \
        "$C_GRY" "$BX_H$BX_H" "$C_OFF$C_CYN$C_B" "$t" "$C_OFF$C_GRY" \
        "$(rep "$BX_H" $((UI_W - n - 4)))" "$C_OFF"
}

# A label above a run of related menu entries.
group() { printf '\n  %s%s%s\n' "$C_DIM$C_B" "$1" "$C_OFF"; }

# item <key> <label> [hint] - one line of a menu. The label column grows if a
# label outruns it, so a long one can never end up glued to its hint.
UI_ITEMW=24
item() {
    local w=$UI_ITEMW n hint=${3:-} hw
    n=$(vislen "$2")
    [ "$n" -ge "$w" ] && w=$((n + 2))
    hw=$((UI_TERM - w - 9))
    if [ -n "$hint" ] && [ "$hw" -ge 6 ]; then
        printf '   %s%2s%s %s%s%s %s%s%s%s\n' \
            "$C_CYN$C_B" "$1" "$C_OFF" "$C_GRY" "$BX_ARR" "$C_OFF" \
            "$(pad_to "$2" "$w")" "$C_DIM" "$(trunc_to "$hint" "$hw")" "$C_OFF"
    else
        printf '   %s%2s%s %s%s%s %s\n' \
            "$C_CYN$C_B" "$1" "$C_OFF" "$C_GRY" "$BX_ARR" "$C_OFF" \
            "$(trunc_to "$2" $((UI_TERM - 9)))"
    fi
}
# item2 is the same line with the current value of a setting on the right.
item2() { item "$@"; }

# state_badge <on|off> - a coloured on/off badge for toggles.
state_badge() {
    if [ "$1" = on ]; then printf '%s%s on%s' "$C_GRN" "$BX_ON" "$C_OFF"
    else printf '%s%s off%s' "$C_GRY" "$BX_OFF" "$C_OFF"; fi
}

# state_dot is the one glyph that says whether a thing is doing its job.
# Running is the only green; not known is grey, because not known is not
# broken.
state_dot() {
    case $1 in
    running) printf '%s%s%s' "$C_OK" "$BX_ON" "$C_OFF" ;;
    idle) printf '%s%s%s' "$C_WARN" "$BX_ON" "$C_OFF" ;;
    stopped) printf '%s%s%s' "$C_WARN" "$BX_OFF" "$C_OFF" ;;
    *) printf '%s%s%s' "$C_MUTE" "$BX_OFF" "$C_OFF" ;;
    esac
}

# ---------------------------------------------------------------------------
# the banner
#
# The name sits in its own frame, centred, so the page opens with one object
# rather than six lines floating above a rule. Two renderings and no third: a
# terminal without a UTF-8 locale draws the block glyphs as question marks.
# ---------------------------------------------------------------------------

banner_art() {
    if [ "$UI_GLYPH" = utf8 ]; then
        printf '%s\n' \
            '██████╗ ██╗███╗   ██╗ ██████╗ ██╗███████╗██╗   ██╗' \
            '██╔══██╗██║████╗  ██║██╔════╝ ██║██╔════╝╚██╗ ██╔╝' \
            '██████╔╝██║██╔██╗ ██║██║  ███╗██║█████╗   ╚████╔╝ ' \
            '██╔═══╝ ██║██║╚██╗██║██║   ██║██║██╔══╝    ╚██╔╝  ' \
            '██║     ██║██║ ╚████║╚██████╔╝██║██║        ██║   ' \
            '╚═╝     ╚═╝╚═╝  ╚═══╝ ╚═════╝ ╚═╝╚═╝        ╚═╝   '
    else
        printf '%s\n' \
            ' ____   ___  _   _   ____  ___  _____ __   __' \
            '|  _ \ |_ _|| \ | | / ___||_ _||  ___|\ \ / /' \
            '| |_) | | | |  \| || |  _  | | | |_    \ V / ' \
            '|  __/  | | | |\  || |_| | | | |  _|    | |  ' \
            '|_|    |___||_| \_| \____||___||_|      |_|  '
    fi
}

banner_line() {
    local text=$1 colour=$2 inner=$((UI_W - 6)) pad
    pad=$(((inner - $(vislen "$text")) / 2))
    [ "$pad" -lt 0 ] && pad=0
    panel_row "$(printf '%*s%s%s%s' "$pad" '' "$colour" "$text" "$C_OFF")"
}

# wipe clears the screen at the top of a screen, and only there. It moves
# the cursor home and erases what is on the screen without touching the
# scrollback, so everything drawn before is still a page up.
wipe() {
    [ -t 1 ] || return 0
    [ "$UI_COLOR" = none ] && return 0
    printf '\033[H\033[2J'
}

banner() {
    local extra=${1:-} line
    wipe
    # The art is fifty wide. Under that it is not a word mark, it is a
    # handful of blocks in the wrong places.
    if [ "$((UI_W - 6))" -lt 50 ]; then
        blank
        printf '  %s%sPINGIFY%s  %sIran %s Kharej tunnel%s\n' \
            "$C_CYN" "$C_B" "$C_OFF" "$C_DIM" "$BX_ARR" "$C_OFF"
        blank
        return 0
    fi
    blank
    panel ""
    while IFS= read -r line; do
        banner_line "$line" "$C_CYN$C_B"
    done < <(banner_art)
    banner_line "by Teejay   $BX_DOT   Iran $BX_ARR Kharej tunnel" "$C_DIM"
    [ -n "$extra" ] && banner_line "$extra" "$C_DIM"
    panel_end
}
screen_top() { banner; }

# ---------------------------------------------------------------------------
# the wizard
#
# The steps run down one page. Nothing is cleared between them, so the
# answers already given stay on screen above the question being asked - which
# is what you want when you are copying the same numbers onto a second
# server. Half a wizard is not a tunnel, so q at any question leaves.
# ---------------------------------------------------------------------------

WIZ_STEP=0
WIZ_ACTIVE=0
WIZ_QUIT=0
wiz_reset() { WIZ_STEP=0; WIZ_ACTIVE=1; WIZ_QUIT=0; }
wiz_end()   { WIZ_ACTIVE=0; WIZ_QUIT=0; }

# wiz <title> [subtitle] - open a step.
wiz() {
    WIZ_STEP=$((WIZ_STEP + 1))
    local t="$WIZ_STEP $BX_DOT $1 " n
    n=$(vislen " $t")
    printf '\n  %s%s%s%s%s%s%s\n\n' \
        "$C_GRY" "$BX_H$BX_H " "$C_OFF$C_CYN$C_B" "$t" "$C_OFF$C_GRY" \
        "$(rep "$BX_H" $((UI_W - n - 5)))" "$C_OFF"
    [ -n "${2:-}" ] && { dim "$2"; blank; }
    return 0
}

# choice <key> <name> <hint> - one option, name and reason on the same line.
# CHOICE_DEF marks the one enter picks, on the line itself.
CHOICE_DEF=""
choice() {
    local mark="   " hint=${3:-}
    if [ "$1" = "$CHOICE_DEF" ]; then
        mark="${C_GRN}${BX_ARR}${C_OFF}  "
        hint="${hint}${hint:+  }${C_GRN}(default)${C_OFF}"
    fi
    printf '  %s%s%2s%s  %s  %s%s%s\n' \
        "$mark" "$C_CYN$C_B" "$1" "$C_OFF" \
        "$(pad_to "${C_B}$2${C_OFF}" 14)" \
        "$C_DIM" "$(trunc_to "$hint" $((UI_TERM - 25)))" "$C_OFF"
}

pause() {
    printf '\n'
    read -rsp "  ${C_DIM}press enter${C_OFF}" _ || true
    printf '\n'
}

# ---------------------------------------------------------------------------
# asking
#
# ask VAR "prompt" ["default"] [validator]
#
# A validator prints why it refused and returns non-zero; the reason is shown
# under the prompt and the question is asked again. q leaves, and once the
# wizard is leaving every later question returns without asking, so it
# unwinds instead of finishing. End of input is not an answer to wait for: a
# piped script that runs out stops here rather than asking for ever.
#
# The locals are prefixed because bash scopes locals dynamically: a caller
# that names its own variable `def` and passed it here would have had it
# overwritten by this function's own.
# ---------------------------------------------------------------------------

ask() {
    local _pk_var=$1 _pk_prompt=$2 _pk_def=${3:-} _pk_check=${4:-} _pk_in _pk_err _pk_rc
    [ "${WIZ_QUIT:-0}" = 1 ] && return 1
    while :; do
        _pk_rc=0
        if [ -n "$_pk_def" ]; then
            read -rp "  ${C_CYN}${BX_ARR}${C_OFF} ${_pk_prompt} ${C_DIM}[${_pk_def}]${C_OFF}${C_B}:${C_OFF} " _pk_in || _pk_rc=1
        else
            read -rp "  ${C_CYN}${BX_ARR}${C_OFF} ${_pk_prompt}${C_B}:${C_OFF} " _pk_in || _pk_rc=1
        fi
        # Standard input has ended. No answer is coming, and a default taken
        # here would answer every remaining question by itself.
        if [ "$_pk_rc" = 1 ]; then
            [ "${WIZ_ACTIVE:-0}" = 1 ] && WIZ_QUIT=1
            return 1
        fi
        [ -z "$_pk_in" ] && _pk_in=$_pk_def
        case $_pk_in in
        q | Q | quit) WIZ_QUIT=1; return 1 ;;
        esac
        if [ -z "$_pk_check" ]; then
            printf -v "$_pk_var" '%s' "$_pk_in"
            return 0
        fi
        if _pk_err=$("$_pk_check" "$_pk_in" 2>&1); then
            printf -v "$_pk_var" '%s' "$_pk_in"
            return 0
        fi
        fail "${_pk_err:-not a valid answer}"
    done
}

# pick VAR "prompt" DEFAULT N - one of the numbers 1..N, and nothing else.
# An empty default means the question has no default: which server this is,
# what transport to speak - an empty enter that quietly means "the first one"
# is how somebody ends up with a tunnel they did not choose.
pick() {
    # Its own name for the answer: ask declares a local of its own with the
    # usual one, and bash scopes locals dynamically, so an answer written
    # into that name would land in ask's copy and this loop would never end.
    local _pk_var=$1 _pk_prompt=$2 _pk_def=${3:-} _pk_n=$4 _pk_ans
    while :; do
        ask _pk_ans "$_pk_prompt" "$_pk_def" v_raw || return 1
        case $_pk_ans in
        '') fail "this one has no default - choose 1 to $_pk_n"; continue ;;
        *[!0-9]*) ;;
        *) if [ "$_pk_ans" -ge 1 ] && [ "$_pk_ans" -le "$_pk_n" ]; then
               printf -v "$_pk_var" '%s' "$_pk_ans"
               return 0
           fi ;;
        esac
        fail "not one of the options - choose 1 to $_pk_n"
    done
}

# confirm "question" [y|n] - the default is no unless said otherwise.
confirm() {
    local _pk_prompt=$1 _pk_def=${2:-n} _pk_in _pk_hint='[y/N]'
    [ "$_pk_def" = y ] && _pk_hint='[Y/n]'
    [ "${WIZ_QUIT:-0}" = 1 ] && return 1
    while :; do
        if ! read -rp "  ${C_YEL}?${C_OFF} $_pk_prompt ${C_DIM}${_pk_hint}${C_OFF}${C_B}:${C_OFF} " _pk_in; then
            [ "${WIZ_ACTIVE:-0}" = 1 ] && WIZ_QUIT=1
            return 1
        fi
        [ -z "$_pk_in" ] && _pk_in=$_pk_def
        case $_pk_in in
        y | Y | yes | YES) return 0 ;;
        n | N | no | NO) return 1 ;;
        # q leaves a wizard. Outside one it is only a no: a flag set here
        # would answer every later question on every screen by itself.
        q | Q) [ "${WIZ_ACTIVE:-0}" = 1 ] && WIZ_QUIT=1; return 1 ;;
        esac
    done
}

# confirm_yes is confirm with the answer already leaning the right way: by the
# time it is asked, everything has been reviewed and the expected reply is yes.
confirm_yes() { confirm "$1" y; }

# menu_key VAR - the number a screen is waiting for. A line, not a keystroke,
# so a screen with more than ten things on it can be answered, and so the
# answer arrives the same way when there is no terminal at all.
# menu_key reads one answer on a screen of numbered items. It answers 0 for
# q as well, so that leaving a screen is the same key everywhere: q used to
# work on the front page and nowhere else, and on one screen it fell out of
# the menu entirely.
menu_key() {
    local _pk_var=$1 _pk_in
    read -rp "  ${C_CYN}${BX_ARR}${C_OFF} select${C_B}:${C_OFF} " _pk_in || return 1
    _pk_in=${_pk_in#"${_pk_in%%[![:space:]]*}"}
    _pk_in=${_pk_in%"${_pk_in##*[![:space:]]}"}
    case $_pk_in in q | Q | b | B) _pk_in=0 ;; esac
    printf -v "$_pk_var" '%s' "$_pk_in"
}

# ---------------------------------------------------------------------------
# validators
# ---------------------------------------------------------------------------

v_any() { [ -n "$1" ] || { echo "say something"; return 1; }; }
v_raw() { return 0; }

v_host() {
    local h=$1 o
    [ -n "$h" ] || { echo "an address is required"; return 1; }
    if [[ $h =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        for o in ${h//./ }; do
            [ "$o" -le 255 ] || { echo "$h: $o is not part of an address"; return 1; }
        done
        return 0
    fi
    case $h in
    *:*) echo "$h is an IPv6 address; the tunnel runs over IPv4 - use the server's IPv4 address"; return 1 ;;
    *[!a-zA-Z0-9.-]* | .* | *. | *..*) echo "$h is not an IPv4 address or a domain"; return 1 ;;
    *[a-zA-Z]*.*) return 0 ;;
    esac
    echo "$h is not an IPv4 address or a domain"
    return 1
}

# v_ip4 is v_host for the kernel-carried transport, whose device takes an
# address and not a name.
v_ip4() {
    v_host "$1" || return 1
    [[ $1 =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "the kernel link needs the IPv4 address itself, not a name"; return 1; }
    return 0
}

v_port() {
    case $1 in '' | *[!0-9]*) echo "a port is a number"; return 1 ;; esac
    { [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; } || { echo "a port is between 1 and 65535"; return 1; }
}

v_octet() {
    case $1 in '' | *[!0-9]*) echo "a number from 1 to 254"; return 1 ;; esac
    { [ "$1" -ge 1 ] && [ "$1" -le 254 ]; } || { echo "between 1 and 254"; return 1; }
}

v_mtu() {
    case $1 in '' | *[!0-9]*) echo "an mtu is a number"; return 1 ;; esac
    { [ "$1" -ge 576 ] && [ "$1" -le 9000 ]; } ||
        { echo "the core takes 576 to 9000; 1320 is what works on most paths"; return 1; }
}

v_token() {
    [ "${#1}" -ge 8 ] || { echo "the core wants at least eight characters"; return 1; }
}

v_name() {
    case $1 in '' | *[!a-zA-Z0-9_-]*) echo "letters, digits, dash and underscore"; return 1 ;; esac
    [ "${#1}" -le 24 ] || { echo "keep it under twenty-five characters"; return 1; }
}

v_number() {
    case $1 in '' | *[!0-9]*) echo "a number"; return 1 ;; esac
}

# ---------------------------------------------------------------------------
# waiting
# ---------------------------------------------------------------------------

# spin "message" command... - runs the command and shows that something is
# happening, so a download or a build never looks frozen. Nothing is drawn
# when nobody is watching.
spin() {
    local msg=$1
    shift
    if [ ! -t 2 ] || [ "$UI_COLOR" = none ]; then "$@"; return $?; fi
    "$@" &
    local pid=$! i=0 frames='|/-\'
    while kill -0 "$pid" 2>/dev/null; do
        printf '\r  %s%s%s %s ' "$C_CYN" "${frames:i++%4:1}" "$C_OFF" "$msg" >&2
        sleep 0.1
    done
    wait "$pid"
    local rc=$?
    printf '\r%*s\r' $((${#msg} + 8)) '' >&2
    return $rc
}

ui_detect
trap 'ui_detect' WINCH
#!/usr/bin/env bash
#
# Where things live, and the handful of operations everything else is built
# from: reading and writing a config, asking systemd what it thinks, and
# asking a running tunnel how it is.
#
# Everything Pingify has lives in one directory, so it is obvious what is
# installed and trivial to back up or delete:
#
#   /root/pingify/                 the tunnels, one .toml each
#   /root/pingify/core/            the core binary
#   /root/pingify/core/src/        its sources, so it can be built with no network
#   /root/pingify/state/           what the manager remembers between runs
#
# Two things stay where they are because nothing else would find them: the
# pingify command on PATH, and the systemd units.
#
# Every path takes its value from the environment if there is one - not for
# flexibility, but so that a test can point the whole script at a temporary
# directory and be certain it cannot touch the machine it is running on.

BASE_DIR=${PINGIFY_BASE_DIR:-/root/pingify}
PINGIFY_BIN=${PINGIFY_BIN:-/usr/local/bin/pingify}
SELF_BIN=$PINGIFY_BIN
CFG_DIR=${PINGIFY_CFG_DIR:-$BASE_DIR}
CORE_DIR=${PINGIFY_CORE_DIR:-$BASE_DIR/core}
CORE_BIN=${PINGIFY_CORE_BIN:-$CORE_DIR/pingify-core}
SRC_DIR=${PINGIFY_SRC_DIR:-$CORE_DIR/src}
STATE_DIR=${PINGIFY_STATE_DIR:-$BASE_DIR/state}
UNIT_DIR=${PINGIFY_UNIT_DIR:-/etc/systemd/system}
CFG_EXT=toml

# The status endpoint listens on the loopback address. One port per tunnel,
# from a base, so two tunnels on one server do not collide.
STATUS_BASE=19900

# And the health port, which the core binds on the tunnel's own private
# address so that the server at the other end can ask it questions. One
# number for every tunnel on every server, and it can be: the address it is
# bound to belongs to one tunnel. It has to be the number the core uses -
# config.DefaultHealthPort is the other half, and a test compares the two.
HEALTH_PORT=19999

# --------------------------------------------------------------------------
# the small things everything uses
# --------------------------------------------------------------------------

have() { command -v "$1" >/dev/null 2>&1; }

# list_has WANT ITEM... - membership without a pipeline. `generator | grep -q`
# is wrong here: grep exits at the first match, the generator takes SIGPIPE,
# and with pipefail the whole thing reports 141 for a question answered yes.
list_has() {
    local want=$1 item
    shift
    for item in "$@"; do [ "$item" = "$want" ] && return 0; done
    return 1
}

require_root() {
    [ "$(id -u)" = 0 ] || die "Pingify has to run as root - it installs services and changes the network. Try: sudo pingify"
}

# 0700 on the config directory because the files in it contain the token.
ensure_dirs() {
    mkdir -p "$CFG_DIR" "$CORE_DIR" "$SRC_DIR" "$STATE_DIR" || return 1
    chmod 0700 "$CFG_DIR" 2>/dev/null
    return 0
}

arch_go() {
    case "$(uname -m)" in
    x86_64 | amd64) printf 'amd64' ;;
    aarch64 | arm64) printf 'arm64' ;;
    *) printf '' ;;
    esac
}

# sed_i writes through a temporary file rather than sed -i, which takes an
# argument on BSD that it refuses on GNU.
sed_i() {
    local script=$1 file=$2 tmp
    tmp=$(mktemp)
    sed "$script" "$file" >"$tmp" && cat "$tmp" >"$file"
    rm -f "$tmp"
}

# fetch <url> <dest> [timeout] - download one file with whatever this machine
# has. The install line is written with curl, but wget is what a bare image
# is most likely to carry.
fetch() {
    local url=$1 dest=$2 t=${3:-120}
    if have curl; then
        curl -fsSL --retry 2 --max-time "$t" -o "$dest" "$url" && return 0
    fi
    if have wget; then
        wget -q --tries=2 --timeout="$t" -O "$dest" "$url" && return 0
    fi
    return 1
}

# --------------------------------------------------------------------------
# the config file
# --------------------------------------------------------------------------
#
# The core reads a small, fixed subset of TOML that this script writes: a
# table header, then key = value lines with a note after a #. Both halves of
# that agreement live in one place each - internal/config for reading, the
# wizard for writing - and these are the only functions in the manager that
# touch the text.

toml_get() {
    local file=$1 table=$2 key=$3
    [ -f "$file" ] || return 0
    awk -v t="$table" -v k="$key" '
        /^[[:space:]]*\[/ { cur = $0; gsub(/[][[:space:]]/, "", cur); next }
        cur == t {
            line = $0
            if (line ~ "^[[:space:]]*" k "[[:space:]]*=") {
                sub(/^[^=]*=[[:space:]]*/, "", line)
                # A quoted value runs to its closing quote, # and all; a
                # bare one runs to the comment, if there is one.
                if (substr(line, 1, 1) == "\"") {
                    line = substr(line, 2)
                    sub(/".*$/, "", line)
                } else {
                    sub(/#.*/, "", line)
                    gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
                }
                print line
                exit
            }
        }
    ' "$file" 2>/dev/null
}

# toml_arr <file> <table> <key> - a one-line list, as its items separated by
# spaces: ["443", "udp:500"] becomes 443 udp:500.
toml_arr() {
    toml_get "$1" "$2" "$3" | tr -d '[]"' | tr ',' ' ' | tr -s ' ' | sed 's/^ //; s/ $//'
}

# toml_set replaces a value in place, keeping the file's order and the note
# beside the value. A key that is not there yet is appended to its table, and
# a table nobody has written yet is created.
toml_set() {
    local file=$1 table=$2 key=$3 val=$4 quoted=${5:-auto}
    case $quoted in
    auto) case $val in '' | *[!0-9]*) quoted=yes ;; *) quoted=no ;; esac ;;
    esac
    [ "$val" = true ] || [ "$val" = false ] && quoted=no
    case $val in -[0-9]*) quoted=no ;; esac

    local rendered=$val
    [ "$quoted" = yes ] && rendered="\"$val\""

    # The value travels in the environment: awk -v reads backslash escapes,
    # and a value with one in it was written out changed.
    PINGIFY_TOML_V=$rendered awk -v t="$table" -v k="$key" '
        BEGIN { done = 0; seen = 0; v = ENVIRON["PINGIFY_TOML_V"] }
        /^[[:space:]]*\[/ {
            if (cur == t && !done) { print k " = " v; done = 1 }
            cur = $0; gsub(/[][[:space:]]/, "", cur)
            if (cur == t) seen = 1
            print; next
        }
        {
            if (cur == t && !done) {
                line = $0; sub(/#.*/, "", line)
                if (line ~ "^[[:space:]]*" k "[[:space:]]*=") {
                    # The note is what follows the old value, and a quoted
                    # value may hold a # of its own.
                    rest = $0; sub(/^[^=]*=[[:space:]]*/, "", rest)
                    if (substr(rest, 1, 1) == "\"") { rest = substr(rest, 2); sub(/^[^"]*"/, "", rest) }
                    note = ""
                    if (match(rest, /[[:space:]]*#.*$/)) note = substr(rest, RSTART)
                    print k " = " v note; done = 1; next
                }
                # A key left at its default is a commented line; setting it
                # takes the comment off rather than adding a second copy.
                if (line == "" && $0 ~ "^# *" k "[[:space:]]*=") {
                    note = ""
                    rest = $0; sub(/^# *[^#]*/, "", rest)
                    if (rest != "") note = " " rest
                    print k " = " v note; done = 1; next
                }
            }
            print
        }
        END {
            if (cur == t && !done) { print k " = " v; done = 1 }
            if (!seen) { print ""; print "[" t "]"; print k " = " v }
        }
    ' "$file" >"$file.tmp" && cat "$file.tmp" >"$file"
    rm -f "$file.tmp"
}

cfg_file() { printf '%s/%s.%s' "$CFG_DIR" "$1" "$CFG_EXT"; }

# cfg_list is every tunnel this server knows about, in a stable order.
cfg_list() {
    local f n
    for f in "$CFG_DIR"/*."$CFG_EXT"; do
        [ -e "$f" ] || continue
        n=${f##*/}
        printf '%s\n' "${n%.$CFG_EXT}"
    done
}

# cfg_apply is the only way a config is changed: copy, edit, ask the core
# whether it will accept the result, and put the old one back if it will not.
cfg_apply() {
    local name=$1 editor=$2 restart=${3:-yes} f out
    f=$(cfg_file "$name")
    [ -f "$f" ] || { fail "there is no tunnel called $name"; return 1; }

    cp -f "$f" "$f.bak"
    if ! "$editor" "$f"; then
        mv -f "$f.bak" "$f"
        return 1
    fi
    if ! out=$("$CORE_BIN" -c "$f" -check 2>&1); then
        mv -f "$f.bak" "$f"
        fail "the core would not accept that change, so nothing was changed:"
        printf '%s\n' "$out" | sed 's/^/       /'
        return 1
    fi
    rm -f "$f.bak"
    [ "$restart" = yes ] && svc_do restart "$name"
    return 0
}

# status_port is derived, not stored: the config carries it, and a tunnel
# created before this existed gets one the first time it is asked.
status_port() {
    local name=$1 p
    p=$(toml_get "$(cfg_file "$name")" status port)
    case $p in '' | *[!0-9]* | 0) p= ;; esac
    if [ -z "$p" ]; then
        local i=0 n
        for n in $(cfg_list); do
            [ "$n" = "$name" ] && { p=$((STATUS_BASE + i)); break; }
            i=$((i + 1))
        done
    fi
    printf '%s' "${p:-$STATUS_BASE}"
}

health_port_of() {
    local p
    p=$(toml_get "$(cfg_file "$1")" status health_port)
    case $p in '' | *[!0-9]*) p=$HEALTH_PORT ;; esac
    printf '%s' "$p"
}

# port_free PORT [PROTO] - nothing is listening there. A UDP socket and a TCP
# socket on the same number are two different things.
# host_listening FAM [MAX] - the ports something on this server already
# listens on, for one family, each with the program's name where root can see
# it: "22 (sshd)", "80 (nginx)". The loopback-only ones are left out; they
# are nobody's business from outside. So are this tool's own: those are the
# tunnel and forwarded ports, and they are listed as such beside this.
host_listening() {
    local fam=${1:-tcp} max=${2:-14} flag=t
    have ss || return 0
    [ "$fam" = udp ] && flag=u
    ss -Hl${flag}np 2>/dev/null | awk -v max="$max" '
        {
            addr = $4; port = addr; sub(/.*:/, "", port)
            if (addr ~ /^127\./ || addr ~ /^\[::1\]/) next
            if (port !~ /^[0-9]+$/) next
            name = ""
            if (match($0, /users:\(\("[^"]+"/)) { name = substr($0, RSTART + 9, RLENGTH - 10) }
            if (name == "pingify-core") next
            if (!(port in seen)) { seen[port] = name; order[++n] = port }
        }
        END {
            for (i = 1; i <= n && i <= max; i++) {
                p = order[i]
                if (seen[p] != "") printf "%s (%s)\n", p, seen[p]; else print p
            }
        }'
}

# host_port_holder PORT FAM - the program on a port, or nothing.
host_port_holder() {
    host_listening "$2" 1000 | awk -v p="$1" '$1 == p { sub(/^[0-9]+ ?/, ""); gsub(/[()]/, ""); print; exit }'
}

show_host_listening() {
    local fam=$1 list
    list=$(host_listening "$fam")
    [ -n "$list" ] || return 0
    printf '%s\n' "$list" | dim_wrap "already listening here on $fam: " "  "
    return 0
}

port_free() {
    local p=$1 proto=${2:-tcp}
    have ss || return 0
    case $proto in
    # No pipeline into grep -q: under pipefail a generator that dies of
    # SIGPIPE reports the port free. See list_has.
    udp) [ -n "$(ss -Hlun "sport = :$p" 2>/dev/null)" ] && return 1 ;;
    *) [ -n "$(ss -Hltn "sport = :$p" 2>/dev/null)" ] && return 1 ;;
    esac
    return 0
}

# --------------------------------------------------------------------------
# systemd
# --------------------------------------------------------------------------

# unit_write writes the units: the template every tunnel runs under, the
# watchdog pass and its timer, and the recycle service the scheduled restart
# uses. Once, at install and on a version change - not on every tunnel.
#
# The template names the core and the config by path, and takes both from
# the constants above rather than writing them out again, so moving either
# cannot leave every tunnel pointing at a file that is not there any more.
unit_write() {
    mkdir -p "$UNIT_DIR" 2>/dev/null
    cat >"$UNIT_DIR/pingify@.service" <<UNIT || return 1
[Unit]
Description=Pingify tunnel %i
Documentation=https://github.com/GreatTeejay/Pingify
After=network-online.target
Wants=network-online.target
# A limit that means something: with it off entirely, a config the core
# refuses restarts every two seconds for ever and fills the journal.
StartLimitIntervalSec=300
StartLimitBurst=20

[Service]
Type=simple
# What a reboot took away is put back before the core starts: the kernel
# link of a GRE FOU tunnel, the AmneziaWG link, the raw TCP firewall rule.
# For every other transport this is a no-op that exits 0.
ExecStartPre=/bin/bash -c 'PINGIFY_NO_MAIN=1 . $PINGIFY_BIN && tunnel_boot %i'
ExecStart=$CORE_BIN -c $CFG_DIR/%i.$CFG_EXT
Restart=always
RestartSec=2

# A raw ICMP socket and a tun device need the first two. The third is for a
# transport that waits on a port below 1024, which behind a CDN is 80 or 443.
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_RAW CAP_NET_BIND_SERVICE
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_RAW CAP_NET_BIND_SERVICE
NoNewPrivileges=yes
LimitNOFILE=1048576
TasksMax=infinity

[Install]
WantedBy=multi-user.target
UNIT
    cat >"$UNIT_DIR/pingify-health.service" <<UNIT || return 1
[Unit]
Description=Pingify health check
ConditionPathExists=$PINGIFY_BIN

[Service]
Type=oneshot
ExecStart=$PINGIFY_BIN --health-check
SyslogIdentifier=pingify-health
UNIT
    cat >"$UNIT_DIR/pingify-health.timer" <<'UNIT' || return 1
[Unit]
Description=Pingify health check every 30s

[Timer]
# Twenty seconds, not sixty: the pass right after a boot is the one that
# catches a tunnel whose link was built before the network was ready.
OnBootSec=20s
OnUnitActiveSec=30s
AccuracySec=5s
Unit=pingify-health.service

[Install]
WantedBy=timers.target
UNIT
    cat >"$UNIT_DIR/pingify-recycle@.service" <<'UNIT' || return 1
[Unit]
Description=Pingify scheduled recycle of tunnel %i

[Service]
Type=oneshot
ExecStart=/bin/systemctl restart pingify@%i.service
SyslogIdentifier=pingify-recycle
UNIT
    systemctl daemon-reload 2>/dev/null || true
    return 0
}

svc_state() {
    local name=$1
    if ! systemctl is-active --quiet "pingify@$name" 2>/dev/null; then
        systemctl is-enabled --quiet "pingify@$name" 2>/dev/null &&
            printf 'stopped' || printf 'disabled'
        return
    fi
    printf 'active'
}

# The machine gets its pings back when the last ICMP tunnel stops.
#
# The core sets net.ipv4.icmp_echo_ignore_all while it runs, and has to: both
# ends of an ICMP tunnel send echo requests, so without it every packet is
# answered twice. What it does not do is give it back. This counts the
# remaining ICMP tunnels first: two of them, one stopped, must not unmute the
# one still running.
# Whether the kernel is muted right now. Its own function so that what the
# machine happens to be doing is not baked into the one below - a test can
# say yes here and get the same answer on any machine.
icmp_echo_muted() { [ "$(cat /proc/sys/net/ipv4/icmp_echo_ignore_all 2>/dev/null)" = 1 ]; }

icmp_echo_restore() {
    local n t
    while IFS= read -r n; do
        [ -n "$n" ] || continue
        t=$(toml_get "$(cfg_file "$n")" transport type)
        [ "$t" = icmp ] || continue
        [ "$(svc_state "$n")" = active ] && return 0
    done < <(cfg_list)
    icmp_echo_muted || return 0
    sysctl -qw net.ipv4.icmp_echo_ignore_all=0 >/dev/null 2>&1 &&
        ok "this server answers pings again"
}

# svc_do never swallows the result: a unit that failed to start is reported
# with the last lines of its journal, not with a green "is running".
svc_do() {
    local what=$1 name=$2
    case $what in
    start | restart)
        rm -f "$STATE_DIR/$name.stopped"
        # A unit that failed often enough to spend its start limit refuses
        # to start again until the count is cleared.
        systemctl reset-failed "pingify@$name" >/dev/null 2>&1
        systemctl "$what" "pingify@$name" 2>&1 | sed 's/^/       /'
        sleep 1
        if systemctl is-active --quiet "pingify@$name"; then
            ok "$name is running"
            return 0
        fi
        fail "$name did not start"
        journalctl -u "pingify@$name" -n 15 --no-pager -o cat 2>/dev/null | sed 's/^/       /'
        return 1
        ;;
    stop | disable)
        systemctl "$what" "pingify@$name" >/dev/null 2>&1
        case $what in
        stop)
            # Written down so the watchdog leaves it stopped: a stop the
            # user asked for is not a tunnel that fell over.
            mkdir -p "$STATE_DIR" 2>/dev/null && : >"$STATE_DIR/$name.stopped"
            ok "$name stopped - the watchdog leaves it until you start it"
            icmp_echo_restore ;;
        *) ok "$name will not start at boot" ;;
        esac
        ;;
    enable)
        rm -f "$STATE_DIR/$name.stopped"
        systemctl enable --now "pingify@$name" 2>&1 | sed 's/^/       /'
        sleep 1
        if systemctl is-active --quiet "pingify@$name"; then
            ok "$name is running"
            return 0
        fi
        fail "$name did not start"
        journalctl -u "pingify@$name" -n 15 --no-pager -o cat 2>/dev/null | sed 's/^/       /'
        return 1
        ;;
    esac
}

# --------------------------------------------------------------------------
# asking a tunnel how it is
# --------------------------------------------------------------------------
#
# One function, because there is one source: the core answers on a loopback
# port with JSON. Nothing here parses English prose out of a log. Sets ST_*
# in the caller; returns non-zero when the tunnel does not answer, and then
# the ST_* are empty rather than stale.

tun_stats() {
    local name=$1 json
    ST_UP= ST_IN= ST_OUT= ST_LOST= ST_GAPS= ST_LATE= ST_UPTIME= ST_DROPPED=
    ST_TRANSPORT= ST_PROFILE= ST_SIDE= ST_INB= ST_OUTB= ST_MODE= ST_FAR_RTT= ST_FAR_SEEN=
    ST_VERSION= ST_TOWIRE= ST_TODEV= ST_NOTOURS= ST_SENDERR= ST_ACTIVE=

    have curl || return 1
    json=$(curl -s --max-time 3 "http://127.0.0.1:$(status_port "$name")/" 2>/dev/null) || return 1
    [ -n "$json" ] || return 1

    ST_VERSION=$(json_field "$json" version)
    ST_UP=$(json_field "$json" up)
    # Bytes in is the only thing on this report that says somebody is at the
    # other end: the core's up means the carrier knows where to send.
    ST_INB=$(json_field "$json" in_bytes)
    ST_OUTB=$(json_field "$json" out_bytes)
    ST_IN=$(json_field "$json" in_mbit)
    ST_OUT=$(json_field "$json" out_mbit)
    ST_LOST=$(json_field "$json" path_lost)
    ST_LATE=$(json_field "$json" path_reordered)
    ST_GAPS=$(json_field "$json" path_gaps)
    ST_UPTIME=$(json_field "$json" uptime_sec)
    ST_DROPPED=$(json_field "$json" dropped)
    ST_TRANSPORT=$(json_field "$json" transport)
    ST_PROFILE=$(json_field "$json" profile)
    ST_SIDE=$(json_field "$json" side)
    ST_MODE=$(json_field "$json" mode)
    ST_FAR_RTT=$(json_field "$json" far_rtt_ms)
    ST_FAR_SEEN=$(json_field "$json" far_seen_sec)
    ST_TOWIRE=$(json_field "$json" to_wire)
    ST_TODEV=$(json_field "$json" to_device)
    ST_NOTOURS=$(json_field "$json" not_ours)
    ST_SENDERR=$(json_field "$json" send_errors)
    # With failover backups, the transport carrying now. Empty without them.
    ST_ACTIVE=$(json_field "$json" transport_active)
    return 0
}

# json_field reads one value out of the core's report, which encoding/json
# writes one field to a line.
json_field() {
    printf '%s' "$1" | awk -v k="\"$2\":" '
        index($0, k) {
            sub(/^[^:]*:[[:space:]]*/, "")
            sub(/,$/, "")
            gsub(/^"|"$/, "")
            print
            exit
        }'
}

# far_report is the other server's own status, fetched across the tunnel. It
# is the one thing on this machine that can see the far end.
far_report() {
    local name=$1 peer hp
    hp=$(health_port_of "$name")
    [ "$hp" -gt 0 ] 2>/dev/null || return 1
    peer=$(peer_addr "$name")
    [ -n "$peer" ] || return 1
    have curl || return 1
    curl -s --max-time 3 "http://$peer:$hp/" 2>/dev/null
}

# tunnel_is_up - one answer for every kind of tunnel: the service runs and
# the far end has been heard from.
tunnel_is_up() {
    local name=$1
    [ "$(svc_state "$name")" = active ] || return 1
    tun_stats "$name" || return 1
    [ "$ST_UP" = true ] && [ "${ST_INB:-0}" != 0 ]
}

round1() {
    case $1 in '' | *[!0-9.]*) printf '%s' "$G_DASH"; return ;; esac
    LC_ALL=C printf '%.1f' "$1" 2>/dev/null || printf '%s' "$G_DASH"
}

human_secs() {
    local s=$1
    case $s in '' | *[!0-9]*) printf '%s' "$G_DASH"; return ;; esac
    if [ "$s" -lt 60 ]; then printf '%ds' "$s"
    elif [ "$s" -lt 3600 ]; then printf '%dm' $((s / 60))
    elif [ "$s" -lt 86400 ]; then printf '%dh %dm' $((s / 3600)) $((s % 3600 / 60))
    else printf '%dd %dh' $((s / 86400)) $((s % 86400 / 3600)); fi
}

# --------------------------------------------------------------------------
# this machine
# --------------------------------------------------------------------------

detect_os() {
    OS_ID=unknown OS_VER=0 OS_PRETTY=unknown
    if [ -r /etc/os-release ]; then
        # shellcheck disable=SC1091
        . /etc/os-release
        OS_ID=${ID:-unknown}
        OS_VER=${VERSION_ID:-0}
        OS_PRETTY=${PRETTY_NAME:-$OS_ID $OS_VER}
    fi
    ARCH=$(uname -m)
    GOARCH=$(arch_go)
}

apt_install() {
    export DEBIAN_FRONTEND=noninteractive
    # A file, not a variable: this runs under spin, in a child, and a
    # variable set there is gone when it returns. One update a day.
    local stamp=$STATE_DIR/apt.updated
    if [ -z "$(find "$stamp" -mmin -1440 2>/dev/null)" ]; then
        apt-get update -qq >/dev/null 2>&1 || warn "apt-get update reported a problem, continuing"
        mkdir -p "$STATE_DIR" 2>/dev/null && : >"$stamp"
    fi
    apt-get install -y -qq "$@" >/dev/null 2>&1
}

ensure_deps() {
    local missing=()
    have curl || missing+=(curl)
    have tar || missing+=(tar)
    have ip && have ss || missing+=(iproute2)
    have iptables || missing+=(iptables)
    have ethtool || missing+=(ethtool)
    if [ ${#missing[@]} -gt 0 ]; then
        if have apt-get; then
            spin "installing ${missing[*]}" apt_install "${missing[@]}" ||
                warn "some packages could not be installed: ${missing[*]}"
        else
            warn "please install by hand: ${missing[*]}"
        fi
    fi
    ensure_dirs
}

public_ip() {
    local ip=
    have ip && ip=$(ip -4 route get 1.1.1.1 2>/dev/null |
        awk '{for (i = 1; i <= NF; i++) if ($i == "src") { print $(i + 1); exit }}')
    printf '%s' "$ip"
}

# srv_info fills the three lines at the top of the home screen: the address
# the outside world sees this server at, and where that address is. Cached
# for a week, because the home screen is drawn on every return and a lookup
# inside that loop is six seconds of nothing each time.
SRV_TTL_DAYS=7
srv_info() {
    [ -n "${SRV_IP:-}" ] && return 0
    local cache=$STATE_DIR/server.info j
    if [ -f "$cache" ] && [ -z "$(find "$cache" -mtime "+$SRV_TTL_DAYS" 2>/dev/null)" ]; then
        IFS='|' read -r SRV_IP SRV_LOC SRV_ORG <"$cache"
    fi
    # The country and the datacentre on the front page come from asking a
    # third party what this server looks like from outside, which tells
    # that third party this server's address. Over TLS, once a week, and
    # PINGIFY_NO_LOOKUP=1 turns it off - the address is then read from the
    # machine itself and the two lines say "not looked up".
    if [ -z "${SRV_IP:-}" ] && [ -z "${PINGIFY_NO_LOOKUP:-}" ] && have curl; then
        j=$(curl -fsS --max-time 6 'https://ip-api.com/json/?fields=query,country,isp' 2>/dev/null)
        SRV_IP=$(printf '%s' "$j" | sed -n 's/.*"query":"\([^"]*\)".*/\1/p')
        SRV_LOC=$(printf '%s' "$j" | sed -n 's/.*"country":"\([^"]*\)".*/\1/p')
        SRV_ORG=$(printf '%s' "$j" | sed -n 's/.*"isp":"\([^"]*\)".*/\1/p')
        [ -n "$SRV_IP" ] && [ -d "$STATE_DIR" ] &&
            printf '%s|%s|%s\n' "$SRV_IP" "$SRV_LOC" "$SRV_ORG" >"$cache"
    fi
    [ -n "${SRV_IP:-}" ] || SRV_IP=$(public_ip)
    [ -n "${SRV_IP:-}" ] || SRV_IP=unknown
    if [ -n "${PINGIFY_NO_LOOKUP:-}" ]; then
        [ -n "${SRV_LOC:-}" ] || SRV_LOC="not looked up"
        [ -n "${SRV_ORG:-}" ] || SRV_ORG="not looked up"
    fi
    [ -n "${SRV_LOC:-}" ] || SRV_LOC=unknown
    [ -n "${SRV_ORG:-}" ] || SRV_ORG=unknown
    return 0
}

# migrate_layout moves a server from the layout before this one, once.
migrate_layout() {
    local moved=0 f n
    for f in /etc/pingify/*.toml /root/Pingify/*.toml; do
        [ -e "$f" ] || continue
        n=${f##*/}
        if [ -e "$CFG_DIR/$n" ]; then
            warn "$f was left behind - $CFG_DIR/$n already exists"
        else
            mv -f "$f" "$CFG_DIR/$n" && moved=1
        fi
    done
    rmdir /etc/pingify 2>/dev/null
    if [ -x /usr/local/bin/pingify-core ] && [ ! -x "$CORE_BIN" ]; then
        mkdir -p "$CORE_DIR"
        mv -f /usr/local/bin/pingify-core "$CORE_BIN" && moved=1
    fi
    rm -f /usr/local/bin/pingify-core
    for f in /var/lib/pingify/*; do
        [ -e "$f" ] || continue
        n=${f##*/}
        if [ -e "$STATE_DIR/$n" ]; then rm -f "$f"; else mv -f "$f" "$STATE_DIR/$n" && moved=1; fi
    done
    rmdir /var/lib/pingify 2>/dev/null
    rm -rf /usr/local/src/pingify
    [ "$moved" = 1 ] || return 0
    chmod 0700 "$CFG_DIR"
    unit_write
    while IFS= read -r n; do
        systemctl is-enabled --quiet "pingify@$n" 2>/dev/null && svc_do restart "$n"
    done < <(cfg_list)
    info "moved the existing setup into $BASE_DIR"
}
#!/usr/bin/env bash
#
# The core: the Go program this script exists to install, and the two things
# needed to get one - its source, and a compiler for it.
#
# Everything in here is shaped by one fact. The server this runs on is in
# Iran and may be able to reach neither a module proxy nor GitHub, so the Go
# sources travel inside this script as plain heredocs and are compiled on the
# machine, offline, with GOPROXY=off. Its two dependencies, uTLS and kcp-go,
# travel the same way, vendored, which is what makes that possible.
#
# There is deliberately no "download a prebuilt binary instead" path. A
# fallback that needs the network is not a fallback for the only machine that
# ever needs one, and carrying it would mean the offline path was never
# exercised and rotted quietly until the day it mattered.
#
# The single step that can want the network is a Go toolchain, and only when
# this machine has none or has one older than the module asks for. That
# download is described in plain words and confirmed before it happens.

# The compiler ensure_go settled on. Empty until it has run.
GO_BIN=

GO_DL_BASE=https://go.dev/dl

# --------------------------------------------------------------------------
# the sources
# --------------------------------------------------------------------------

# write_core_sources lays the module out under DIR with its paths intact -
# cmd/pingify and internal/*, not a heap of basenames in one directory. The
# old bundle did flatten them, which was harmless while the core was a single
# package and stopped compiling the hour it became a module.
#
# The body below is generated. build.sh replaces the marker line with one
# mkdir -p covering every directory, then one quoted heredoc per source file and a base64 tarball of the vendored modules, each
# writing into "$d" - so that variable name is part of the agreement with
# build.sh and cannot be renamed here. build.sh then sources the built script,
# calls this function into a temporary tree, diffs it against the repository
# and compiles the result, so the round trip is checked rather than hoped for.
write_core_sources() {
    local d=$1
    mkdir -p "$d"
    mkdir -p "$d/cmd/pingify" "$d/internal/buf" "$d/internal/carrier" "$d/internal/config" "$d/internal/forward" "$d/internal/kernel" "$d/internal/link" "$d/internal/logging" "$d/internal/status"
    cat > "$d/go.mod" <<'PINGIFY_GO_SOURCE_EOF' || return 1
module pingify

go 1.24.0

require (
	github.com/refraction-networking/utls v1.8.2
	github.com/xtaci/kcp-go/v5 v5.6.72
)

require (
	github.com/andybalholm/brotli v1.0.6 // indirect
	github.com/klauspost/compress v1.17.4 // indirect
	github.com/klauspost/cpuid/v2 v2.2.6 // indirect
	github.com/klauspost/reedsolomon v1.12.0 // indirect
	github.com/pkg/errors v0.9.1 // indirect
	github.com/tjfoc/gmsm v1.4.1 // indirect
	golang.org/x/crypto v0.45.0 // indirect
	golang.org/x/net v0.47.0 // indirect
	golang.org/x/sys v0.38.0 // indirect
	golang.org/x/time v0.14.0 // indirect
)
PINGIFY_GO_SOURCE_EOF
    cat > "$d/go.sum" <<'PINGIFY_GO_SOURCE_EOF' || return 1
