package main

import (
	"flag"
	"fmt"
	"os"
	"os/signal"
	"syscall"
	"time"

	"pingify/internal/carrier"
	"pingify/internal/config"
	"pingify/internal/forward"
	"pingify/internal/kernel"
	"pingify/internal/link"
	"pingify/internal/logging"
	"pingify/internal/status"
)

// Pingify, the core.
//
// A tunnel between a server in Iran and a server abroad. The Iran server is
// the one users reach; the abroad server is the one with the internet on the
// other side of it. What matters about it, in the order it matters: latency,
// then throughput, then staying up. Nothing else is worth a millisecond.
//
// This is the second core. The first one worked, and worked well - by the end
// it was level with the tunnel it was being compared against on ping and ahead
// of it under load. What it did not have was a shape: it was written outward
// from a first working version over two days, so its structure was the order
// in which things were discovered rather than the way the problem is actually
// laid out.
//
// The way the problem is actually laid out:
//
//	a carrier moves messages between the two servers        carrier.go
//	over UDP, or ICMP, or something dressed as TLS          udp.go, ...
//	and one thing rides on it, chosen by the mode:
//	    the private link - one IP packet per message        link.go
//	    forwarded ports  - many connections per carrier     forward.go
//
// Transports are added one at a time and each is measured on the real path
// between Tehran and Frankfurt before the next one starts. What was learned
// from the first core is in docs/measured.md, and none of it is re-learned
// here by accident: every finding in that file is either satisfied by this
// code or has not been reached yet.
const version = "1.0.1"

func main() {
	// Before anything else, because everything else is downstream of having
	// somewhere to run. See sched.go.
	widenScheduler()

	var (
		cfgPath = flag.String("c", "", "path to the config file")
		check   = flag.Bool("check", false, "read the config, say whether it is good, and stop")
		showVer = flag.Bool("version", false, "print the version and stop")
		ask     = flag.String("status", "", "ask a running tunnel how it is (host:port or just a port) and stop")
		healthz = flag.String("healthz", "", "exit 0 only if the tunnel at this address is up")
	)
	flag.Parse()

	if *showVer {
		fmt.Println("pingify-core " + version)
		return
	}
	if *healthz != "" {
		r, err := status.Fetch(*healthz)
		if err != nil || !r.Up {
			os.Exit(1)
		}
		return
	}
	if *ask != "" {
		r, err := status.Fetch(*ask)
		if err != nil {
			logging.Die("could not ask the tunnel at %s: %v", *ask, err)
		}
		status.Print(r)
		return
	}
	if *cfgPath == "" {
		logging.Die("no config: pass -c /path/to/config.toml")
	}

	cfg, err := config.Load(*cfgPath)
	if err != nil {
		logging.Die("%s: %v", *cfgPath, err)
	}
	if *check {
		// The port list is the forwarder's to read, and the side that binds
		// it is the one a bad spec would stop at start - so it is read here,
		// where the manager asks before it writes anything.
		if cfg.Mode == "forward" && cfg.Side == config.SideIran {
			if _, err := forward.ParseAll(cfg.Forward.Ports); err != nil {
				logging.Die("%s: forward.ports: %v", *cfgPath, err)
			}
		}
		fmt.Printf("%s: good - %s side, %s mode, %s transport\n",
			*cfgPath, cfg.Side, cfg.Mode, cfg.Transport.Type)
		return
	}
	logging.SetLevel(cfg.Level)

	logging.Info("core: pingify-core %s starting: %s, %s side, %s over %s",
		version, cfg.Name, cfg.Side, cfg.Mode, cfg.Transport.Type)

	// One transport this process does not carry: the kernel holds the device
	// and the bytes never come up here. All that is left to do is answer for
	// it. See internal/kernel.
	if cfg.Transport.Type == "grefou" {
		watchKernel(cfg)
		return
	}

	car, err := carrier.Open(cfg)
	if err != nil {
		logging.Die("carrier: %v", err)
	}

	// Two kinds of tunnel, and the file says which. A private link is a tun
	// device with an address at each end; a forward tunnel has no device at
	// all - the IRAN side answers on ports and each connection crosses as a
	// stream of its own.
	var l tunnel
	if cfg.Mode == "forward" {
		f, err := forward.New(cfg, car)
		if err != nil {
			car.Close()
			logging.Die("forward: %v", err)
		}
		if err := f.Start(); err != nil {
			car.Close()
			logging.Die("forward: %v", err)
		}
		l = f
	} else {
		pl, err := link.New(cfg, car)
		if err != nil {
			car.Close()
			logging.Die("private link: %v", err)
		}
		pl.Start()
		l = pl
	}
	go car.Run()
	// Both ends of a private link send these. Only the side that dialled
	// used to, so on an idle link the dialling side heard nothing back and
	// could not tell a far end that was quiet from one that had gone - it
	// reported itself up through the whole of an outage. A keepalive is a
	// few bytes every ten seconds, and a far end too old to send its own
	// still takes them.
	if cfg.Dials() || cfg.Mode == "tun" {
		go car.Keepalive(time.Duration(cfg.Transport.Keepalive) * time.Second)
	}
	go reportEvery(30*time.Second, car, l, cfg.Mode == "forward")
	go status.New(cfg, version, car, l).Serve(cfg.StatusPort, cfg.HealthPort)

	logging.Info("core: running")

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	logging.Info("core: stopping")
	l.Close()
	car.Close()
	logging.Info("%s", l)
}

// watchKernel runs the tunnel whose bytes the kernel moves: it answers the
// status and health ports from the device's counters and does nothing else,
// until systemd stops it. The device itself is the manager's - it is made
// before this starts and unmade after it stops, with the offload setting and
// the firewall rules that belong to it.
func watchKernel(cfg *config.Config) {
	l, err := kernel.New(cfg)
	if err != nil {
		logging.Die("%s: %v", cfg.Transport.Type, err)
	}
	go l.Watch()
	go status.New(cfg, version, l, l).Serve(cfg.StatusPort, cfg.HealthPort)
	logging.Info("core: running")

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	logging.Info("core: stopping")
	_ = l.Close()
	logging.Info("%s", l)
}

// tunnel is what main needs from either kind: the status server's two
// counters, a close, and a line for the log on the way out.
type tunnel interface {
	Dropped() uint64
	Packets() (toWire, toDevice uint64)
	Close() error
	String() string
}

func max64(a, b uint64) uint64 {
	if a > b {
		return a
	}
	return b
}

// since is now minus then, and never less than nothing.
func since(now, then uint64) uint64 {
	if now < then {
		return 0
	}
	return now - then
}

// reportEvery says what the tunnel has been doing, but only when it has been
// doing something. A line every thirty seconds saying nothing happened fills
// a log with the absence of news, and the one line that matters is then in the
// middle of a thousand that do not.
// How long a tunnel may say nothing at all before it says it is still
// there. Long enough that a quiet week is a handful of lines, short enough
// that somebody reading the journal can tell a live tunnel from a dead one.
const idleReport = 30 * time.Minute

func reportEvery(every time.Duration, c carrier.Full, l tunnel, forwarding bool) {
	tk := time.NewTicker(every)
	defer tk.Stop()
	var lastRx, lastTx uint64
	var lastMissing, lastLate, lastGaps uint64
	var lastDropped uint64
	quiet := time.Duration(0)
	for range tk.C {
		rx, tx, bad, replay, errs := c.Counters()
		secs := every.Seconds()
		in := float64(rx-lastRx) * 8 / secs / 1e6
		out := float64(tx-lastTx) * 8 / secs / 1e6
		// A tunnel with nobody on it still moves a keepalive every ten
		// seconds, which used to print "0.0 Mbit/s in, 0.0 Mbit/s out"
		// twice a minute for ever - a hundred and twenty lines an hour
		// saying nothing, and the journal of a quiet week was nothing
		// else. A line now means traffic, or the half hour passing.
		if in >= 0.05 || out >= 0.05 {
			quiet = 0
			logging.Info("carrier: %.1f Mbit/s in, %.1f Mbit/s out", in, out)
		} else if quiet += every; quiet >= idleReport {
			quiet = 0
			logging.Info("carrier: up, and nobody has sent anything for %s", idleReport)
		}
		if bad > 0 || replay > 0 {
			logging.Debug("carrier: %d not ours, %d already seen", bad, replay)
		}
		// How much was lost matters less than how it was lost. Losses spread
		// one at a time are noise a congestion window shrugs off; the same
		// number arriving in runs is a window halved once per run.
		if missing, late, gaps := c.Lost(); missing != lastMissing || late != lastLate {
			// since is a subtraction that cannot go backwards. The missing
			// count does go backwards now - a packet that arrives late stops
			// being a missing one - and an unsigned subtraction that went
			// negative printed "the path lost 18446744073709551551", which is
			// how this was found.
			lost := since(missing, lastMissing)
			gapped := since(gaps, lastGaps)
			run := float64(lost) / float64(max64(gapped, 1))
			logging.Info("carrier: the path lost %d and reordered %d in the last %s (%d gaps, %.0f packets each)",
				lost, since(late, lastLate), every, gapped, run)
			lastMissing, lastLate, lastGaps = missing, late, gaps
		}
		if errs > 0 {
			logging.Debug("carrier: %d sends failed", errs)
		}
		// Dropped is a total, not a rate. Reporting the total made one bad
		// half-second warn again every thirty seconds for as long as the
		// tunnel ran - a server three days up said "4 packets dropped" 8640
		// times about the same four. What is worth a line is the growth.
		if d := l.Dropped(); d > lastDropped {
			n := since(d, lastDropped)
			if forwarding {
				logging.Warn("forward: %d records could not be put on the wire and were dropped", n)
			} else {
				logging.Warn("link: %d packets arrived faster than the device would take them, and were dropped", n)
			}
			lastDropped = d
		}
		lastRx, lastTx = rx, tx
	}
}
