package carrier

import (
	"fmt"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"pingify/internal/buf"
	"pingify/internal/config"
	"pingify/internal/logging"
)

// Failover: one tunnel over several transports, one of them at a time.
//
// The side that waits listens on every member at once and decides nothing. It
// sends on whichever member records last arrived on, which is the member the
// other side is using - so the two servers cannot disagree about it, and
// nothing has to be said to switch.
//
// The side that dials decides. It runs one member, and when nothing has
// arrived on it for long enough it opens the next, waits for it to connect,
// and closes the old one. Closing is what moves the connections: every stream
// that rode the old member is offered again down the new one, by the same
// resume that carries a stream over one dead carrier connection. While a
// backup carries, the primary is tried with one connection that carries only
// keepalives, and the tunnel moves back when that connection has been answered
// for long enough to trust.
//
// Everything here is a stream carrier. That is what forwarding needs, and it
// is what lets a record written for one member cross on another: the headroom
// is the largest any member wants and the payload the smallest any allows.
type failover struct {
	cfg     *config.Config
	dials   bool
	members []*member

	head   int // the largest headroom any member needs
	maxPay int // the smallest payload any member allows

	active atomic.Int32 // the member in use, on the side that dials

	// The member records last arrived on, on the side that waits, or -1.
	carrying atomic.Int32

	onPacket   atomic.Pointer[func([]byte)]
	onLinkDown atomic.Pointer[func(int)]
	rttOf      atomic.Pointer[func() time.Duration]
	keepalive  atomic.Int64 // nanoseconds; zero until main asks for keepalives

	switchAfter, returnAfter, probeEvery time.Duration
	prefer                               string

	// A member's counters go with it when it closes, and a total that went
	// backwards would read to the status page as the path taking bytes back.
	retired struct {
		sync.Mutex
		rx, tx, bad, replay, errs, missing, late, gaps uint64
	}

	done chan struct{}
	once sync.Once
}

type member struct {
	idx  int
	kind string
	cfg  *config.Config

	car   atomic.Pointer[streamCarrier] // nil while it is not open
	fresh bool                          // car has never been run, so it may be
	heard atomic.Int64                  // unix nanos of the last record through it
	kept  atomic.Pointer[streamCarrier] // the carrier its keepalive loop was started for
}

// How members are chosen among the ones that answer.
const (
	preferOrder   = "order"   // the first in the file that answers
	preferFastest = "fastest" // the least round trip, measured by the probes
)

// Variables rather than constants only so a test does not wait a quarter of
// a minute for each of them.
var (
	// How often a probe's connection says something. Its answers are the only
	// thing that proves a member carries, and they are timed, so it is more
	// often than a tunnel's own keepalive.
	probeKeepalive = time.Second

	// How long a probe may go unanswered before its member is given up.
	probePatience = 5 * time.Second

	// How long a hunt waits for members to answer, and how long after the
	// first answer it goes on waiting for a better one.
	huntWait  = streamDialWait
	huntGrace = 2 * time.Second
)

func newFailover(cfg *config.Config) (*failover, error) {
	c := &failover{
		cfg:         cfg,
		dials:       cfg.Dials(),
		switchAfter: time.Duration(cfg.Failover.SwitchAfter) * time.Second,
		returnAfter: time.Duration(cfg.Failover.ReturnAfter) * time.Second,
		probeEvery:  time.Duration(cfg.Failover.ProbeEvery) * time.Second,
		prefer:      cfg.Failover.Prefer,
		done:        make(chan struct{}),
	}
	c.carrying.Store(-1)
	var kinds []string
	for i, m := range cfg.Members() {
		mc := cfg.For(m)
		car, err := c.build(mc)
		if err != nil {
			c.Close()
			return nil, fmt.Errorf("%s on %d: %v", m.Type, m.Port, err)
		}
		mem := &member{idx: i, kind: m.Type, cfg: mc, fresh: true}
		c.members = append(c.members, mem)
		c.attach(mem, car)
		if car.Headroom() > c.head {
			c.head = car.Headroom()
		}
		if p := car.MaxPayload(); c.maxPay == 0 || p < c.maxPay {
			c.maxPay = p
		}
		kinds = append(kinds, fmt.Sprintf("%s/%d", m.Type, m.Port))
	}
	how := "in that order"
	if c.prefer == preferFastest {
		how = "whichever answers fastest"
	}
	logging.Info("failover: %s, %s; moving on after %s of silence",
		strings.Join(kinds, " then "), how, c.switchAfter)
	return c, nil
}

// build opens one member's carrier. On the side that waits it answers
// keepalives, because on a member nobody is using an answered keepalive is
// the only thing that can prove it works.
func (c *failover) build(mc *config.Config) (*streamCarrier, error) {
	full, err := open(mc)
	if err != nil {
		return nil, err
	}
	sc, ok := full.(*streamCarrier)
	if !ok {
		_ = full.Close()
		return nil, fmt.Errorf("%s is not a transport that forwards", mc.Transport.Type)
	}
	if !c.dials {
		sc.echo = true
	}
	return sc, nil
}

// attach makes car the member's carrier and passes what it hears upward.
func (c *failover) attach(m *member, car *streamCarrier) {
	car.OnPacket(func(b []byte) {
		m.heard.Store(time.Now().UnixNano())
		if !c.dials {
			if prev := c.carrying.Swap(int32(m.idx)); prev >= 0 && int(prev) != m.idx {
				go c.leftBehind(int(prev), m.idx)
			}
		}
		if f := c.onPacket.Load(); f != nil {
			(*f)(b)
		}
	})
	car.OnLinkDown(func(slot int) { c.linkDown(m, slot) })
	m.car.Store(car)
}

// linkDown passes a member's dead connection up, when streams may have been
// riding it. On the side that dials every open member is one that carried or
// is about to. On the side that waits, a member nothing has arrived on for a
// while was not carrying anything - it is the primary being tried, or a
// member left behind by a switch - and passing its connections up would have
// every stream offered again for nothing, and reset the ones too new to be.
func (c *failover) linkDown(m *member, slot int) {
	if !c.dials {
		quiet := time.Since(time.Unix(0, m.heard.Load()))
		if quiet > c.recent() {
			return
		}
	}
	if f := c.onLinkDown.Load(); f != nil {
		(*f)(slot)
	}
}

// leftBehind closes what the side that dials left on a member it moved away
// from, on the side that waits.
//
// That side closed its own connections, but when the move was forced the
// closing never arrives: whatever stopped the member carrying stops the FIN
// too, and to this end the connections are still open. Measured with the
// primary's port blocked mid-download: a writer sat in a write to one of them
// for the twenty seconds the kernel allows, everything queued behind it -
// the end of a stream among it - waited with it, and the program at the other
// end sat on a connection that had already been given up. Records arriving
// on another member are the proof the move happened, so once they have kept
// arriving for a moment the old member's connections are closed here, which
// ends those writes at once and offers their streams down the new member.
func (c *failover) leftBehind(prev, now int) {
	select {
	case <-c.done:
		return
	case <-time.After(leftBehindWait):
	}
	old := c.members[prev]
	if c.carrying.Load() != int32(now) || time.Since(time.Unix(0, old.heard.Load())) < leftBehindWait {
		return // records still arrive on it: not a move, or not finished
	}
	if car := old.car.Load(); car != nil && car.Up() {
		logging.Info("failover: the other side moved from %s to %s; closing what it left on %s",
			old.kind, c.members[now].kind, old.kind)
		car.dropLinks()
	}
}

// leftBehindWait is how long records must have kept arriving on the new member,
// and stopped on the old one, before the old one's connections are closed.
var leftBehindWait = 2 * time.Second

// recent is how long ago a member may have carried records and still count as
// carrying: three rounds of the tunnel's pings and keepalives.
func (c *failover) recent() time.Duration {
	d := 3 * time.Duration(c.cfg.Transport.Keepalive) * time.Second
	if d < 30*time.Second {
		d = 30 * time.Second
	}
	return d
}

// sender is the carrier to send on now.
//
// The side that dials sends on the member in use, and on any other member
// still open while a switch is under way. The side that waits sends on the
// member records last arrived on, among those with a connection.
func (c *failover) sender() *streamCarrier {
	if c.dials {
		if car := c.members[c.active.Load()].car.Load(); car != nil && car.Up() {
			return car
		}
	}
	var best *streamCarrier
	var bestHeard int64 = -1
	for _, m := range c.members {
		car := m.car.Load()
		if car == nil || !car.Up() {
			continue
		}
		if h := m.heard.Load(); h > bestHeard {
			best, bestHeard = car, h
		}
	}
	return best
}

// fit moves a record built for the largest headroom to where this member
// wants it, and returns the member's view of the same buffer.
func (c *failover) fit(car *streamCarrier, bp *[]byte) {
	extra := c.head - car.Headroom()
	if extra <= 0 {
		return
	}
	b := *bp
	copy(b[car.Headroom():], b[c.head:])
	*bp = b[:len(b)-extra]
}

func (c *failover) Headroom() int   { return c.head }
func (c *failover) MaxPayload() int { return c.maxPay }
func (c *failover) Burst() int      { return 1 }

func (c *failover) Up() bool { return c.sender() != nil }

func (c *failover) OnPacket(f func([]byte))     { c.onPacket.Store(&f) }
func (c *failover) OnLinkDown(f func(slot int)) { c.onLinkDown.Store(&f) }

func (c *failover) SendFlow(flow uint32, bp *[]byte) error {
	car := c.sender()
	if car == nil {
		buf.Put(bp)
		return ErrNoPeer
	}
	if len(*bp) < c.head {
		buf.Put(bp)
		return nil
	}
	c.fit(car, bp)
	return car.SendFlow(flow, bp)
}

// FlowUp asks the member in use, which knows its connections.
func (c *failover) FlowUp(flow uint32) bool {
	car := c.sender()
	if car == nil {
		return false
	}
	return car.FlowUp(flow)
}

func (c *failover) Send(bp *[]byte) error {
	car := c.sender()
	if car == nil {
		buf.Put(bp)
		return ErrNoPeer
	}
	if len(*bp) < c.head {
		buf.Put(bp)
		return nil
	}
	c.fit(car, bp)
	return car.Send(bp)
}

type failoverSender struct{ c *failover }

func (c *failover) NewSender() Sender { return &failoverSender{c: c} }

func (s *failoverSender) Send(bps []*[]byte) {
	for _, bp := range bps {
		_ = s.c.Send(bp)
	}
}

// Active is the transport in use, for the status page.
func (c *failover) Active() string {
	if c.dials {
		return c.members[c.active.Load()].kind
	}
	var best string
	var bestHeard int64 = -1
	for _, m := range c.members {
		if h := m.heard.Load(); h > bestHeard && m.car.Load() != nil {
			best, bestHeard = m.kind, h
		}
	}
	return best
}

// Members is every transport this tunnel can run on, in order.
func (c *failover) Members() []string {
	out := make([]string, len(c.members))
	for i, m := range c.members {
		out[i] = m.kind
	}
	return out
}

func (c *failover) Run() {
	if !c.dials {
		for _, m := range c.members {
			if car := m.car.Load(); car != nil {
				m.fresh = false
				go car.Run()
			}
		}
		<-c.done
		return
	}
	c.start(0)
	c.decide()
}

// Keepalive is remembered and applied to whichever member is running; a
// member opened later is given it when it starts.
func (c *failover) Keepalive(every time.Duration) {
	c.keepalive.Store(int64(every))
	if c.dials {
		c.keepAlive(c.members[c.active.Load()])
	}
	<-c.done
}

// keepAlive starts the keepalive loop for a member's carrier, once. Main asks
// for keepalives and the first member starts on goroutines of their own, in
// either order, and a carrier given two loops would say everything twice.
func (c *failover) keepAlive(m *member) {
	ka := time.Duration(c.keepalive.Load())
	car := m.car.Load()
	if ka <= 0 || car == nil {
		return
	}
	if old := m.kept.Load(); old != car && m.kept.CompareAndSwap(old, car) {
		go car.Keepalive(ka)
	}
}

// start runs a member's carrier on the side that dials, opening a new one if
// the one it has has been run before - a stream carrier that has been closed
// cannot be opened again.
func (c *failover) start(i int) *streamCarrier {
	m := c.members[i]
	car := m.car.Load()
	if car == nil || !m.fresh {
		nc, err := c.build(m.cfg)
		if err != nil {
			logging.Warn("failover: could not open %s: %v", m.kind, err)
			return nil
		}
		c.attach(m, nc)
		car = nc
	}
	m.fresh = false
	go car.Run()
	c.keepAlive(m)
	return car
}

// retire closes a member's carrier and keeps its counters.
func (c *failover) retire(m *member) {
	car := m.car.Load()
	if car == nil {
		return
	}
	// Kept before it is taken out, not after: a Counters() call in between
	// dropped this member's totals for one sample, which is the one thing
	// the totals must never do.
	c.keep(car)
	m.car.CompareAndSwap(car, nil)
	_ = car.Close()
}

func (c *failover) keep(car *streamCarrier) {
	rx, tx, bad, replay, errs := car.Counters()
	missing, late, gaps := car.Lost()
	c.retired.Lock()
	c.retired.rx += rx
	c.retired.tx += tx
	c.retired.bad += bad
	c.retired.replay += replay
	c.retired.errs += errs
	c.retired.missing += missing
	c.retired.late += late
	c.retired.gaps += gaps
	c.retired.Unlock()
}

// decide is the side that dials watching the member in use, once a second,
// for as long as the tunnel runs.
//
// Two things can happen. The member in use goes quiet, and then every other
// member is tried at once and the best that answers is taken - not the next
// in the list, which may be as dead as this one, and not one at a time with
// a full silence spent on each. Or the tunnel is on a member that is not the
// best it could be on, and then the better ones are tried now and then, one
// connection each, and the best that has answered for long enough is taken
// back.
func (c *failover) decide() {
	tk := time.NewTicker(time.Second)
	defer tk.Stop()

	since := time.Now() // when the member in use started, or last carried
	var lastRx uint64
	var probes []*probe
	nextProbe := time.Now().Add(c.probeEvery)
	stopProbes := func() {
		for _, p := range probes {
			p.stop()
		}
		probes = nil
	}
	defer stopProbes()

	// Whether anything has ever arrived, on any member, and whether that first
	// contact came on a backup. A tunnel whose far end is not there yet - the
	// second server not set up, which is every new pair for its first minute -
	// hunts for it like any other silence, and whichever member it is on when
	// the far end appears is where it is found. On a backup that is not a
	// failure of the primary, and waiting out return_after_sec for it would
	// leave a pair made a minute ago running on its backup, with a warning on
	// it, for no reason: seen on the real pair, straight after the wizard. So
	// the better members are tried at once, and taken as soon as one answers.
	heardEver, quick := false, false

	for {
		select {
		case <-c.done:
			return
		case <-tk.C:
		}
		now := time.Now()
		i := int(c.active.Load())
		m := c.members[i]

		if car := m.car.Load(); car != nil {
			if rx, _, _, _, _ := car.Counters(); rx != lastRx {
				if !heardEver && i != c.bestRank(-1) {
					quick, nextProbe = true, now
				}
				heardEver = true
				lastRx, since = rx, now
			}
		}

		if now.Sub(since) > c.switchAfter {
			stopProbes()
			why := fmt.Sprintf("nothing has arrived on %s for %s", m.kind, c.switchAfter.Round(time.Second))
			if j := c.hunt(i, huntWait); j >= 0 {
				c.switchTo(j, why, false)
			} else {
				logging.Warn("failover: %s, and no other member answers either", why)
			}
			since, lastRx = time.Now(), 0
			nextProbe = time.Now().Add(c.probeEvery)
			continue
		}

		// Is there anywhere better to be?
		if c.returnAfter == 0 {
			continue
		}
		cands := c.better(i)
		if len(cands) == 0 {
			continue
		}
		if len(probes) == 0 {
			if now.After(nextProbe) {
				probes = c.probeAll(cands)
				if len(probes) == 0 {
					nextProbe = now.Add(c.probeEvery)
				}
			}
			continue
		}
		healthyFor := c.returnAfter
		if quick {
			healthyFor = 0
		}
		var healthy []*probe
		alive := 0
		for _, p := range probes {
			switch p.state(now, healthyFor) {
			case probeHealthy:
				healthy = append(healthy, p)
				alive++
			case probeWaiting:
				alive++
			}
		}
		if alive == 0 {
			stopProbes()
			quick = false
			nextProbe = now.Add(c.probeEvery)
			continue
		}
		best := c.pick(healthy)
		if best == nil {
			continue
		}
		// With the round trip deciding, the member in use stays unless
		// something beats it by a margin worth a move: a tenth, so two members
		// a millisecond apart do not trade places every probe.
		if c.prefer == preferFastest && !quick {
			if cur := c.activeRTT(); cur > 0 && best.rtt()*10 > cur*9 {
				continue
			}
		}
		why := fmt.Sprintf("%s has answered for %s", best.m.kind, c.returnAfter.Round(time.Second))
		if quick {
			why = fmt.Sprintf("the other side was first reached on %s, and %s answers too", m.kind, best.m.kind)
		} else if c.prefer == preferFastest {
			why = fmt.Sprintf("%s answers in %s, the least of any member", best.m.kind, best.rtt().Round(time.Millisecond))
		}
		stopProbes()
		quick = false
		if c.switchTo(best.m.idx, why, true) {
			since, lastRx = time.Now(), 0
		}
		nextProbe = time.Now().Add(c.probeEvery)
	}
}

// bestRank is the member the tunnel would rather be on than any other, in the
// file's order: the first one, or the first one that is not `except`.
func (c *failover) bestRank(except int) int {
	for _, m := range c.members {
		if m.idx != except {
			return m.idx
		}
	}
	return -1
}

// better is every member worth trying while i is in use. In the file's order
// that is everything above i. When the round trip decides it is every other
// member: never i itself, because a probe's connection names slot 0, and on
// the side that waits it would take that slot from the connection that is
// carrying the tunnel. The member in use is measured by the tunnel's own
// pings instead - see SetRTT.
func (c *failover) better(i int) []*member {
	var out []*member
	for _, m := range c.members {
		if m.idx == i {
			continue
		}
		if c.prefer == preferFastest || m.idx < i {
			out = append(out, m)
		}
	}
	return out
}

// SetRTT is where the round trip of the member in use comes from: the
// forward layer measures it with a ping record every few seconds, and the
// carrier cannot see that on its own.
func (c *failover) SetRTT(f func() time.Duration) { c.rttOf.Store(&f) }

func (c *failover) activeRTT() time.Duration {
	if f := c.rttOf.Load(); f != nil {
		return (*f)()
	}
	return 0
}

// hunt tries every member but `except` at once and returns the best that
// answers, or -1 when none does within the wait. In the file's order the hunt
// ends the moment the best-ranked candidate answers; otherwise, and when the
// round trip decides, the others are given a moment to answer too.
func (c *failover) hunt(except int, wait time.Duration) int {
	var cands []*member
	for _, m := range c.members {
		if m.idx != except {
			cands = append(cands, m)
		}
	}
	probes := c.probeAll(cands)
	defer func() {
		for _, p := range probes {
			p.stop()
		}
	}()
	if len(probes) == 0 {
		return -1
	}
	deadline := time.Now().Add(wait)
	var first time.Time
	for {
		select {
		case <-c.done:
			return -1
		case <-time.After(100 * time.Millisecond):
		}
		now := time.Now()
		var answered []*probe
		for _, p := range probes {
			if p.answers.Load() > 0 {
				answered = append(answered, p)
			}
		}
		best := c.pick(answered)
		if best != nil {
			if first.IsZero() {
				first = now
			}
			if (c.prefer == preferOrder && best.m.idx == c.bestRank(except)) || now.Sub(first) >= huntGrace {
				return best.m.idx
			}
		}
		if now.After(deadline) {
			if best != nil {
				return best.m.idx
			}
			return -1
		}
	}
}

// pick is the best of some probes that have answered: the first in the
// file's order, or the one with the least round trip.
func (c *failover) pick(ps []*probe) *probe {
	var best *probe
	for _, p := range ps {
		if best == nil {
			best = p
			continue
		}
		switch c.prefer {
		case preferFastest:
			if r := p.rtt(); r > 0 && (best.rtt() == 0 || r < best.rtt()) {
				best = p
			}
		default:
			if p.m.idx < best.m.idx {
				best = p
			}
		}
	}
	return best
}

func (c *failover) probeAll(ms []*member) []*probe {
	var out []*probe
	for _, m := range ms {
		if p := c.newProbe(m); p != nil {
			out = append(out, p)
		}
	}
	return out
}

// switchTo moves the tunnel to member i. The new member connects before the
// old one is closed, so records are never without somewhere to go; when the
// move is back to a member that has only been tried, and it will not connect,
// the move is abandoned and the member in use carries on.
func (c *failover) switchTo(i int, why string, careful bool) bool {
	from := c.members[c.active.Load()]
	to := c.members[i]
	car := c.start(i)
	if car == nil {
		return false
	}
	// Waiting for the new member to connect is worth it only when the old one
	// still carries. A move forced by silence has nothing to keep open, and
	// when the far end is not there at all every member is silent - waiting a
	// dial's full fifteen seconds on each would only make finding it slower.
	if careful {
		deadline := time.Now().Add(streamDialWait)
		for !car.Up() && time.Now().Before(deadline) {
			select {
			case <-c.done:
				return false
			case <-time.After(100 * time.Millisecond):
			}
		}
		if !car.Up() {
			logging.Info("failover: %s did not connect; staying on %s", to.kind, from.kind)
			c.retire(to)
			return false
		}
	}
	moved := time.Now().UnixNano()
	c.active.Store(int32(i))
	if from == to {
		return true
	}
	logging.Warn("failover: moving from %s to %s - %s", from.kind, to.kind, why)
	if careful {
		// The old member still works, and the other side is still sending on
		// it until records from here arrive on the new one. Closed now, what
		// it sends in between goes nowhere: KCP says nothing when a session
		// closes, and measured on the way back to the primary, six seconds of
		// a sixteen megabit stream went into a session nobody was reading,
		// more than a stream is allowed to hold for a resend, and the stream
		// was reset. So the old member stays open until the far side is heard
		// on the new one.
		deadline := time.Now().Add(streamDialWait)
		for to.heard.Load() < moved && time.Now().Before(deadline) {
			select {
			case <-c.done:
				return true
			case <-time.After(100 * time.Millisecond):
			}
		}
	}
	c.retire(from)
	return true
}

func (c *failover) Close() error {
	c.once.Do(func() { close(c.done) })
	for _, m := range c.members {
		if car := m.car.Swap(nil); car != nil {
			_ = car.Close()
		}
	}
	return nil
}

func (c *failover) Counters() (rx, tx, bad, replay, errs uint64) {
	c.retired.Lock()
	rx, tx, bad, replay, errs = c.retired.rx, c.retired.tx, c.retired.bad, c.retired.replay, c.retired.errs
	c.retired.Unlock()
	for _, m := range c.members {
		if car := m.car.Load(); car != nil {
			a, b, d, e, f := car.Counters()
			rx, tx, bad, replay, errs = rx+a, tx+b, bad+d, replay+e, errs+f
		}
	}
	return
}

func (c *failover) Lost() (missing, late, gaps uint64) {
	c.retired.Lock()
	missing, late, gaps = c.retired.missing, c.retired.late, c.retired.gaps
	c.retired.Unlock()
	for _, m := range c.members {
		if car := m.car.Load(); car != nil {
			a, b, d := car.Lost()
			missing, late, gaps = missing+a, late+b, gaps+d
		}
	}
	return
}

// A probe is one member tried with one connection that carries nothing but
// keepalives, each of them timed, so the probe can say whether the member
// answers and how quickly.
type probe struct {
	m       *member
	car     *streamCarrier
	started time.Time
	heard   atomic.Int64 // unix nanos of the last answer
	best    atomic.Int64 // the least round trip seen, in nanos; zero is none
	answers atomic.Uint64
	done    chan struct{}
	once    sync.Once
}

type probeResult int

const (
	probeWaiting probeResult = iota
	probeFailed
	probeHealthy
)

func (c *failover) newProbe(m *member) *probe {
	pc := *m.cfg
	pc.Transport.Connections = 1
	car, err := c.build(&pc)
	if err != nil {
		logging.Debug("failover: could not try %s: %v", m.kind, err)
		return nil
	}
	p := &probe{m: m, car: car, started: time.Now(), done: make(chan struct{})}
	go car.Run()
	go p.run()
	logging.Debug("failover: trying %s", m.kind)
	return p
}

// run sends a keepalive every probeKeepalive and times the answer to it. The
// side that waits answers every keepalive on a member with backups, and
// nothing else ever arrives on a probe's connection, so a byte in is an
// answer to the byte last sent.
func (p *probe) run() {
	tk := time.NewTicker(probeKeepalive)
	defer tk.Stop()
	for {
		select {
		case <-p.done:
			return
		case <-tk.C:
		}
		if !p.car.Up() {
			continue
		}
		rx0, _, _, _, _ := p.car.Counters()
		sent := time.Now()
		if err := p.car.Send(buf.Take(p.car.Headroom(), 0)); err != nil {
			continue
		}
		for time.Now().Before(sent.Add(probeKeepalive)) {
			select {
			case <-p.done:
				return
			case <-time.After(10 * time.Millisecond):
			}
			if rx, _, _, _, _ := p.car.Counters(); rx != rx0 {
				now := time.Now()
				p.heard.Store(now.UnixNano())
				p.answers.Add(1)
				if d := int64(now.Sub(sent)); p.best.Load() == 0 || d < p.best.Load() {
					p.best.Store(d)
				}
				break
			}
		}
	}
}

func (p *probe) rtt() time.Duration { return time.Duration(p.best.Load()) }

// state is what a probe says about its member: waiting for an answer, failed
// because the answers stopped or never came, or healthy because they have
// kept coming for as long as was asked.
func (p *probe) state(now time.Time, healthyFor time.Duration) probeResult {
	heard := time.Unix(0, p.heard.Load())
	if p.answers.Load() == 0 {
		heard = p.started
	}
	if now.Sub(heard) > probePatience {
		return probeFailed
	}
	if p.answers.Load() > 0 && now.Sub(p.started) >= healthyFor {
		return probeHealthy
	}
	return probeWaiting
}

func (p *probe) stop() {
	p.once.Do(func() {
		close(p.done)
		_ = p.car.Close()
	})
}
