    cat > "$d/internal/carrier/fallback.go" <<'PINGIFY_GO_SOURCE_EOF' || return 1
package carrier

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/tls"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"sync"
	"time"

	utls "github.com/refraction-networking/utls"

	"pingify/internal/config"
	"pingify/internal/logging"
)

// TLS FALLBACK: a TLS server that is a route to somebody else's website until
// it is shown the token.
//
// There are two observers to satisfy on this path and they are not the same
// one. TCP UTLS answers the first: what a passive filter reads of a TLS
// connection is the ClientHello, and ours is Chrome's rather than Go's. This
// transport answers the second, which is the half that gets a server blocked
// within days of being found.
//
// Watching is cheap, so a censor that suspects an address simply connects to
// it and looks. A server that answers that probe with a self-signed
// certificate for a name it has no business serving has confessed, and no
// amount of care over the hello saves it.
//
// So this end never answers a probe at all. It reads the ClientHello, looks
// for an authenticator where a browser puts its session ticket, and if it is
// not there the whole connection - starting with the hello already read - is
// spliced to the site named in its SNI. The prober completes a real handshake
// with the real site, gets that site's real certificate, and reads its real
// home page, because that is precisely what happened: for that connection this
// server was a route to www.microsoft.com and nothing else.
//
// The authenticator rides in the session id, which is where a browser puts 32
// bytes and so do we. Sixteen are random and sixteen are an HMAC over them and
// the half minute they were made in, under a key derived from the token. To
// anything without the token they are 32 bytes of a session ticket, which is
// what 32 random looking bytes in that field are everywhere else on the
// internet.
//
// What this does not do: it does not serve the real site's certificate to us,
// so a censor that both probes the address and watches a genuine visitor's
// session could see two certificates for one name. Closing that needs the far
// site's handshake forwarded live, which is a much larger machine and buys
// nothing against either observer on its own.
const (
	// What a browser sends, so the authenticator is sized to fit exactly.
	// Anything else in that field is a fingerprint of its own.
	fallbackAuthLen = 32

	// How closely the two clocks have to agree. Half a minute, checked either
	// side, so a server that has never heard of NTP still works.
	fallbackWindow = 30 * time.Second

	// Who to be when the config gives no name to borrow. Unremarkable in any
	// traffic log, and up.
	fallbackDefaultSNI = "www.microsoft.com"

	// A hello that never arrives must not hold a goroutine: a prober that
	// opens a socket and says nothing is the cheapest attack there is.
	fallbackHelloWait = 10 * time.Second
)

var errNotOurs = errors.New("no token in the hello")

func newFallbackCarrier(cfg *config.Config) (*streamCarrier, error) {
	c, err := newStreamCarrier(cfg, "fallback", tcpLenLen)
	if err != nil {
		return nil, err
	}

	m := hmac.New(sha256.New, []byte("pingify fallback session id v1"))
	m.Write([]byte(cfg.Token))
	f := &fallback{key: m.Sum(nil), sni: fallbackSNI(cfg), seen: newNonceSet(),
		self: localAddresses(cfg), busy: make(chan struct{}, fallbackSplices)}

	host := cfg.DialHost()
	addr := net.JoinHostPort(host, fmt.Sprint(cfg.Transport.Port))

	c.dial = func() (net.Conn, framing, error) {
		nc, err := net.DialTimeout("tcp4", addr, streamDialWait)
		if err != nil {
			return nil, nil, err
		}
		prepStream(nc)
		// The connect had a timeout; the handshake needs one of its own.
		_ = nc.SetDeadline(time.Now().Add(streamDialWait))
		u, err := f.hello(nc)
		if err != nil {
			_ = nc.Close()
			return nil, nil, err
		}
		_ = nc.SetDeadline(time.Time{})
		return u, lenFraming{}, nil
	}

	if cfg.Dials() {
		logging.Info("carrier: dialling %s as a browser visiting %s", addr, f.sni)
		return c, nil
	}

	conf, err := utlsServerConfig(cfg)
	if err != nil {
		return nil, err
	}
	c.accept = func(nc net.Conn) (net.Conn, framing, error) {
		return f.answer(nc, conf)
	}
	logging.Info("carrier: anything without the token is spliced to %s", f.sni)
	return c, nil
}

// fallbackSNI is the name this end pretends to be, which is the name the far
// end dials when there is one. A tunnel dialled by address has no name to
// borrow, and borrows the default.
func fallbackSNI(cfg *config.Config) string {
	h := cfg.DialHost()
	if config.IsName(h) {
		return h
	}
	return fallbackDefaultSNI
}

type fallback struct {
	key  []byte
	sni  string
	seen *nonceSet
	// self is every address this host answers on. A hello naming our own
	// domain would otherwise have this server open a connection to itself,
	// land back in answer, fail the check and splice again - a level of
	// goroutines and descriptors per turn until there were none left.
	self map[string]bool
	// busy bounds the conversations held open for probers at once. Each one
	// is two connections and three goroutines for as long as it lasts.
	busy chan struct{}
}

const (
	fallbackSplices    = 64
	fallbackSpliceLife = 2 * time.Minute
)

// localAddresses is what self holds: the interfaces' addresses and the two
// the config names.
func localAddresses(cfg *config.Config) map[string]bool {
	m := map[string]bool{}
	if addrs, err := net.InterfaceAddrs(); err == nil {
		for _, a := range addrs {
			if ipn, ok := a.(*net.IPNet); ok {
				m[ipn.IP.String()] = true
			}
		}
	}
	for _, h := range []string{cfg.Transport.Iran, cfg.Transport.Kharej} {
		if ip := net.ParseIP(h); ip != nil {
			m[ip.String()] = true
		}
	}
	return m
}

// token builds the 32 bytes that go in the session id.
func (f *fallback) token(nonce []byte, at time.Time) []byte {
	out := make([]byte, fallbackAuthLen)
	copy(out[:16], nonce)
	m := hmac.New(sha256.New, f.key)
	m.Write(out[:16])
	var w [8]byte
	binary.BigEndian.PutUint64(w[:], uint64(at.Unix()/int64(fallbackWindow/time.Second)))
	m.Write(w[:])
	copy(out[16:], m.Sum(nil)[:16])
	return out
}

// valid says whether a session id is one of ours, made within a window either
// side of now, and not one already used.
func (f *fallback) valid(sid []byte) bool {
	if len(sid) != fallbackAuthLen {
		return false
	}
	now := time.Now()
	for _, d := range []time.Duration{0, -fallbackWindow, fallbackWindow} {
		want := f.token(sid[:16], now.Add(d))
		if hmac.Equal(want[16:], sid[16:]) {
			var n [16]byte
			copy(n[:], sid[:16])
			return f.seen.accept(n, now)
		}
	}
	return false
}

// hello dials with Chrome's ClientHello and our own session id inside it.
//
// The certificate is not checked and cannot be: the name presented is a site
// we are only pretending to be. The token is what authenticates the
// connection, and it does so before a byte of ours is sent.
func (f *fallback) hello(nc net.Conn) (net.Conn, error) {
	nonce := make([]byte, 16)
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}
	u := utls.UClient(nc, &utls.Config{
		ServerName:         f.sni,
		InsecureSkipVerify: true,
	}, utls.HelloChrome_Auto)
	if err := u.BuildHandshakeState(); err != nil {
		return nil, fmt.Errorf("hello: %v", err)
	}
	u.HandshakeState.Hello.SessionId = f.token(nonce, time.Now())
	if err := u.MarshalClientHello(); err != nil {
		return nil, fmt.Errorf("hello: %v", err)
	}
	if err := u.Handshake(); err != nil {
		return nil, fmt.Errorf("handshake with %s: %v", f.sni, err)
	}
	return u, nil
}

// answer decides what an arriving connection is before speaking a word of TLS
// to it, which is this whole transport in one function.
func (f *fallback) answer(nc net.Conn, conf *tls.Config) (net.Conn, framing, error) {
	_ = nc.SetReadDeadline(time.Now().Add(fallbackHelloWait))
	hello, sid, sni, err := readClientHello(nc)
	if err != nil {
		return nil, nil, err
	}

	if !f.valid(sid) {
		// Not ours, or a replay. Hand the whole thing to the site it asked
		// for and stay out of the way. This holds the goroutine for as long
		// as that conversation lasts, which is what makes it convincing - so
		// the deadline the accept path set has to go first.
		_ = nc.SetDeadline(time.Time{})
		f.splice(nc, hello, sni)
		return nil, nil, errNotOurs
	}

	// Ours. Finish the handshake here, with the hello put back in front.
	_ = nc.SetReadDeadline(time.Time{})
	ts := tls.Server(&prefixConn{Conn: nc, pre: hello}, conf)
	if err := ts.Handshake(); err != nil {
		return nil, nil, fmt.Errorf("tls: %v", err)
	}
	return ts, lenFraming{}, nil
}

// splice is the connection this server does not own, carried to the site it
// asked for. What comes back is that site's real certificate and real page,
// because it is that site answering.
func (f *fallback) splice(nc net.Conn, hello []byte, sni string) {
	defer func() { _ = nc.Close() }()
	select {
	case f.busy <- struct{}{}:
		defer func() { <-f.busy }()
	default:
		return // every seat is taken; a closed connection is a fine answer
	}
	// A hello with no name gets the default site, never our own name: our
	// own name is this server, and the connection would come straight back.
	if sni == "" {
		sni = fallbackDefaultSNI
	}
	// The name was written by whoever is probing, and this server is about
	// to open a connection to it on their behalf. A public address is what
	// an SNI proxy does all day; a private one is a way into whatever this
	// machine can reach and the internet cannot, so those get the same answer
	// as a bad hello - nothing.
	ip := publicAddressOf(sni)
	if ip == nil || f.self[ip.String()] {
		return
	}
	up, err := net.DialTimeout("tcp", net.JoinHostPort(ip.String(), "443"), 8*time.Second)
	if err != nil {
		// There is nothing useful to say to a prober. Closing is what a
		// server with nothing on that port does.
		return
	}
	defer func() { _ = up.Close() }()
	// A prober's conversation ends within the minute; one that does not is
	// somebody holding a seat, and the seat is taken back.
	_ = nc.SetDeadline(time.Now().Add(fallbackSpliceLife))
	_ = up.SetDeadline(time.Now().Add(fallbackSpliceLife))
	if _, err := up.Write(hello); err != nil {
		return
	}
	// Both directions, and the end of one is passed on as a half close rather
	// than taken as the end of the connection. Closing on the first of the two
	// cuts the answer off mid-flight: a probing browser sees the page arrive
	// and the connection break, which is its own kind of confession.
	done := make(chan struct{}, 2)
	go func() { _, _ = io.Copy(up, nc); halfClose(up); done <- struct{}{} }()
	go func() { _, _ = io.Copy(nc, up); halfClose(nc); done <- struct{}{} }()
	<-done
	<-done
}

// halfClose says "nothing more from this end" without ending the conversation,
// which is what lets the other direction finish.
func halfClose(c net.Conn) {
	if tc, ok := c.(*net.TCPConn); ok {
		_ = tc.CloseWrite()
	}
}

// A nonce is good once. Without this, a recording of one valid hello opens a
// connection here for as long as the window lasts - which is exactly the probe
// this transport exists to survive: the replay cannot finish the handshake,
// but it does not need to. It only needs to see this server answer with its
// own certificate instead of Microsoft's.
//
// Three generations, not two. A hello is accepted from a window either side of
// now, so one made by a clock half a minute ahead is still valid two windows
// after it was first seen - and with two generations its nonce had been
// forgotten by then. Recorded, replayed a minute later, accepted.
const nonceGens = 3

type nonceSet struct {
	mu   sync.Mutex
	gen  int64
	gens [nonceGens]map[[16]byte]struct{} // [0] is this window, [1] the last, and so on
}

func newNonceSet() *nonceSet {
	s := &nonceSet{}
	for i := range s.gens {
		s.gens[i] = map[[16]byte]struct{}{}
	}
	return s
}

// accept remembers a nonce and reports whether it was new.
func (s *nonceSet) accept(n [16]byte, at time.Time) bool {
	g := at.Unix() / int64(fallbackWindow/time.Second)
	s.mu.Lock()
	defer s.mu.Unlock()
	if d := g - s.gen; d != 0 {
		if d < 0 || d >= nonceGens {
			// The clock went backwards, or so long passed that nothing
			// remembered can still be valid. Start clean either way.
			for i := range s.gens {
				s.gens[i] = map[[16]byte]struct{}{}
			}
		} else {
			for ; d > 0; d-- {
				copy(s.gens[1:], s.gens[:nonceGens-1])
				s.gens[0] = map[[16]byte]struct{}{}
			}
		}
		s.gen = g
	}
	for i := range s.gens {
		if _, ok := s.gens[i][n]; ok {
			return false
		}
	}
	s.gens[0][n] = struct{}{}
	return true
}

// prefixConn puts bytes already read back in front of a connection.
type prefixConn struct {
	net.Conn
	pre []byte
}

func (p *prefixConn) Read(b []byte) (int, error) {
	if len(p.pre) > 0 {
		n := copy(b, p.pre)
		p.pre = p.pre[n:]
		return n, nil
	}
	return p.Conn.Read(b)
}

// readClientHello reads exactly one TLS record and pulls the session id and
// the server name out of it. The raw bytes come back too, because whatever
// happens next has to send them on: this end must not consume a byte it might
// have to hand to somebody else.
func readClientHello(c net.Conn) (raw, sessionID []byte, sni string, err error) {
	var hdr [5]byte
	if _, err = io.ReadFull(c, hdr[:]); err != nil {
		return nil, nil, "", err
	}
	// A handshake record, and one big enough to be a hello but not absurd.
	if hdr[0] != 0x16 {
		return nil, nil, "", errNotOurs
	}
	n := int(binary.BigEndian.Uint16(hdr[3:5]))
	if n < 42 || n > 16384 {
		return nil, nil, "", errNotOurs
	}
	raw = make([]byte, 5+n)
	copy(raw, hdr[:])
	if _, err = io.ReadFull(c, raw[5:]); err != nil {
		return nil, nil, "", err
	}
	sessionID, sni = parseClientHello(raw[5:])
	return raw, sessionID, sni, nil
}

// parseClientHello walks the handshake far enough to find the session id and
// the server name. Anything malformed returns nothing, which sends the
// connection to the real site - the safe direction to be wrong in.
func parseClientHello(b []byte) (sessionID []byte, sni string) {
	if len(b) < 4 || b[0] != 0x01 { // handshake type, then a 3-byte length
		return nil, ""
	}
	b = b[4:]
	if len(b) < 34 { // client_version, random
		return nil, ""
	}
	b = b[34:]
	if len(b) < 1 {
		return nil, ""
	}
	sl := int(b[0])
	if len(b) < 1+sl {
		return nil, ""
	}
	sessionID = b[1 : 1+sl]
	b = b[1+sl:]
	if len(b) < 2 { // cipher suites
		return sessionID, ""
	}
	cl := int(binary.BigEndian.Uint16(b[:2]))
	if len(b) < 2+cl {
		return sessionID, ""
	}
	b = b[2+cl:]
	if len(b) < 1 { // compression methods
		return sessionID, ""
	}
	ml := int(b[0])
	if len(b) < 1+ml {
		return sessionID, ""
	}
	b = b[1+ml:]
	if len(b) < 2 { // extensions
		return sessionID, ""
	}
	el := int(binary.BigEndian.Uint16(b[:2]))
	b = b[2:]
	if len(b) < el {
		return sessionID, ""
	}
	b = b[:el]
	for len(b) >= 4 {
		typ := binary.BigEndian.Uint16(b[:2])
		ln := int(binary.BigEndian.Uint16(b[2:4]))
		if len(b) < 4+ln {
			return sessionID, ""
		}
		if typ == 0x0000 { // server_name
			return sessionID, parseSNI(b[4 : 4+ln])
		}
		b = b[4+ln:]
	}
	return sessionID, ""
}

func parseSNI(b []byte) string {
	if len(b) < 2 { // server_name_list length
		return ""
	}
	b = b[2:]
	for len(b) >= 3 {
		typ := b[0]
		ln := int(binary.BigEndian.Uint16(b[1:3]))
		if len(b) < 3+ln {
			return ""
		}
		if typ == 0 {
			name := string(b[3 : 3+ln])
			if validHostname(name) {
				return name
			}
			return ""
		}
		b = b[3+ln:]
	}
	return ""
}

// publicAddressOf resolves a name a prober asked for and hands back one public
// address of it, or nil. The address is what gets dialled, rather than the
// name a second time, so what was checked is what is connected to.
func publicAddressOf(host string) net.IP {
	ips, err := net.LookupIP(host)
	if err != nil {
		return nil
	}
	for _, ip := range ips {
		if ip4 := ip.To4(); ip4 != nil && publicIP(ip4) {
			return ip4
		}
	}
	return nil
}

// publicIP is "an address the whole internet could have reached by itself":
// not loopback, not the private ranges, not link local, not the carrier grade
// block, not multicast.
func publicIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() ||
		ip.IsMulticast() || ip.IsUnspecified() {
		return false
	}
	if ip4 := ip.To4(); ip4 != nil && ip4[0] == 100 && ip4[1]&0xc0 == 64 {
		return false // 100.64.0.0/10
	}
	return true
}

// validHostname keeps a forged SNI from turning this server into an open relay
// to anywhere: what comes back out of it is only ever a hostname.
func validHostname(s string) bool {
	if len(s) == 0 || len(s) > 253 {
		return false
	}
	dot := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		case c == '-' || c == '_':
		case c == '.':
			dot = true
		default:
			return false
		}
	}
	return dot
}
PINGIFY_GO_SOURCE_EOF
    cat > "$d/internal/carrier/fec.go" <<'PINGIFY_GO_SOURCE_EOF' || return 1
package carrier

import (
	"encoding/binary"
	"sync"
	"sync/atomic"

	"pingify/internal/buf"
	"pingify/internal/logging"
)

// Repairing a lost packet without asking for it again.
//
// Every datagram carrier here loses packets, because that is what a path does
// and none of them pretend otherwise: the TCP inside the tunnel notices a
// round trip later and asks again. On an eighty millisecond path, a third of a
// percent of loss is a third of a percent of every transfer waiting a sixth of
// a second for something it had already sent.
//
// This is the other answer. Every N packets, one more goes out that is the
// exclusive-or of those N. Lose any one of the N and the far end rebuilds it
// from the rest and the parity, at once, with nothing asked for and no round
// trip. Lose two out of the same N and the parity is no help, and TCP does
// what it would have done anyway.
//
// It costs one packet in N of bandwidth and nothing else.
//
// It is a wrapper around a carrier rather than a layer inside one, which is
// what keeps it away from the transports with no use for it: a stream carrier
// cannot lose a packet, so it is never wrapped.
const (
	// kind, group, index. Four bytes in front of every packet, and the group
	// is its own field rather than something worked out from the framer's
	// sequence number because this sits above the framer and cannot see it.
	fecHdr    = 4
	fecData   = 0
	fecParity = 1

	fecMinGroup = 4
	fecMaxGroup = 32

	// How many groups the receiver keeps at once. A packet and the parity for
	// its group can arrive a little apart, and this is how much reordering
	// that tolerates before the group is given up on.
	fecGroups = 8
)

type fecCarrier struct {
	Full
	n int

	// The sending side. The lock is not optional: a carrier may have one
	// sender per device queue, and two of them filling one group would fold
	// each other's packets into the same parity.
	mu     sync.Mutex
	parity []byte
	group  uint16
	index  uint8

	rx       *fecRecovery
	repaired uint64
	onPacket atomic.Pointer[func([]byte)]
}

// WrapFEC puts parity on a carrier, or returns it untouched when the transport
// cannot take it - see noParity, which is where the two reasons are written
// down.
func WrapFEC(c Full, n int, blocked bool) Full {
	if n <= 0 || blocked {
		return c
	}
	if n < fecMinGroup {
		n = fecMinGroup
	}
	if n > fecMaxGroup {
		n = fecMaxGroup
	}
	f := &fecCarrier{Full: c, n: n, rx: newFECRecovery()}
	c.OnPacket(f.fromWire)
	logging.Info("carrier: forward error correction, one parity packet per %d", n)
	return f
}

func (f *fecCarrier) Headroom() int   { return f.Full.Headroom() + fecHdr }
func (f *fecCarrier) MaxPayload() int { return f.Full.MaxPayload() - fecHdr }

func (f *fecCarrier) OnPacket(fn func([]byte)) { f.onPacket.Store(&fn) }

func (f *fecCarrier) Send(bp *[]byte) error {
	grp, n, par := f.stamp(*bp)
	err := f.Full.Send(bp)
	if par != nil {
		f.sendParity(grp, n, par)
	}
	return err
}

func (f *fecCarrier) NewSender() Sender {
	return &fecSender{f: f, inner: f.Full.NewSender()}
}

type fecSender struct {
	f     *fecCarrier
	inner Sender
}

// The parity goes out after the packets it covers, not before.
//
// It was sent from inside the stamping, which put it on the wire ahead of the
// last packet of its own group - so the far end saw a group one short, decided
// that one was lost, rebuilt it perfectly, delivered it, and then delivered
// the real one when it arrived a moment later. Every group, with no loss
// anywhere: a duplicate of every tenth packet.
func (s *fecSender) Send(bps []*[]byte) {
	type parcel struct {
		grp uint16
		n   uint8
		p   []byte
	}
	var out []parcel
	for _, bp := range bps {
		if grp, n, par := s.f.stamp(*bp); par != nil {
			out = append(out, parcel{grp, n, par})
		}
	}
	s.inner.Send(bps)
	for _, o := range out {
		s.f.sendParity(o.grp, o.n, o.p)
	}
}

// stamp writes this packet's header, folds it into the parity being built,
// and sends that parity when the group is full.
//
// The fold happens here rather than afterwards because the buffer goes back
// to the pool the moment the carrier below has written it: the parity has to
// be accumulated as the packets go past, not built from them later.
func (f *fecCarrier) stamp(b []byte) (uint16, uint8, []byte) {
	head := f.Full.Headroom()
	if len(b) < head+fecHdr {
		return 0, 0, nil
	}
	body := b[head+fecHdr:]

	f.mu.Lock()
	b[head] = fecData
	binary.BigEndian.PutUint16(b[head+1:head+3], f.group)
	b[head+3] = f.index

	f.foldIn(body)
	f.index++
	var out []byte
	var grp uint16
	var n uint8
	if int(f.index) >= f.n {
		out = append([]byte(nil), f.parity...)
		grp, n = f.group, f.index
		f.group++
		f.index = 0
		f.parity = f.parity[:0]
	}
	f.mu.Unlock()
	return grp, n, out
}

// foldIn folds one payload into the parity. Its length goes in with it, in two
// bytes at the front, because the packets in a group are not all the same size
// and the far end has to know how long the one it rebuilds was.
func (f *fecCarrier) foldIn(body []byte) {
	need := 2 + len(body)
	for len(f.parity) < need {
		f.parity = append(f.parity, 0)
	}
	var l [2]byte
	binary.BigEndian.PutUint16(l[:], uint16(len(body)))
	f.parity[0] ^= l[0]
	f.parity[1] ^= l[1]
	for i, c := range body {
		f.parity[2+i] ^= c
	}
}

func (f *fecCarrier) sendParity(group uint16, n uint8, p []byte) {
	head := f.Full.Headroom()
	bp := buf.Take(head, fecHdr+len(p))
	b := *bp
	b[head] = fecParity
	binary.BigEndian.PutUint16(b[head+1:head+3], group)
	b[head+3] = n
	copy(b[head+fecHdr:], p)
	_ = f.Full.Send(bp)
}

// fromWire is every datagram the carrier below received. It runs on that
// carrier's read goroutine, which is what lets the recovery state below have
// no lock on it.
func (f *fecCarrier) fromWire(b []byte) {
	if len(b) < fecHdr {
		return
	}
	kind := b[0]
	group := binary.BigEndian.Uint16(b[1:3])
	idx := b[3]
	body := b[fecHdr:]

	if kind == fecData {
		f.up(body)
		f.rx.data(group, idx, body)
		return
	}
	if rebuilt := f.rx.parity(group, idx, body); rebuilt != nil {
		atomic.AddUint64(&f.repaired, 1)
		f.up(rebuilt)
	}
}

func (f *fecCarrier) up(b []byte) {
	if fn := f.onPacket.Load(); fn != nil {
		(*fn)(b)
	}
}

// Repaired is how many packets came back from parity rather than from the
// wire, which is the one number that says whether this is earning its
// bandwidth.
func (f *fecCarrier) Repaired() uint64 { return atomic.LoadUint64(&f.repaired) }

// --------------------------------------------------------------------------
// the receiving side
// --------------------------------------------------------------------------

// One group being watched: what has arrived, folded together, and how much of
// it. A group is finished the moment its parity can be used or the moment its
// slot is needed for a newer one.
type fecGroup struct {
	id    uint16
	used  bool
	seen  uint8  // how many data packets of this group arrived
	acc   []byte // the exclusive-or of what arrived, lengths included
	done  bool
	scrap []byte
}

type fecRecovery struct {
	// A carrier with more than one reader - ICMP has up to four - feeds
	// this from all of them at once. The lock is per packet and costs a
	// few nanoseconds, like the framer's.
	mu     sync.Mutex
	groups [fecGroups]fecGroup
}

func newFECRecovery() *fecRecovery { return &fecRecovery{} }

// slot finds the entry for a group, taking over the oldest if this is a group
// nothing has been seen of yet.
func (r *fecRecovery) slot(id uint16) *fecGroup {
	var free *fecGroup
	for i := range r.groups {
		g := &r.groups[i]
		if g.used && g.id == id {
			return g
		}
		if !g.used {
			free = g
		}
	}
	if free == nil {
		// The oldest, by the distance the group counter has moved since.
		oldest := &r.groups[0]
		for i := range r.groups {
			if int16(id-r.groups[i].id) > int16(id-oldest.id) {
				oldest = &r.groups[i]
			}
		}
		free = oldest
	}
	*free = fecGroup{id: id, used: true, acc: free.acc[:0], scrap: free.scrap}
	return free
}

func (r *fecRecovery) data(id uint16, _ uint8, body []byte) {
	r.mu.Lock()
	defer r.mu.Unlock()
	g := r.slot(id)
	if g.done {
		return
	}
	foldInto(&g.acc, body)
	g.seen++
	// Nothing to do until the parity says how many there were.
}

// parity folds the parity in and, if exactly one packet of the group is
// missing, hands back what it was.
func (r *fecRecovery) parity(id uint16, n uint8, body []byte) []byte {
	r.mu.Lock()
	defer r.mu.Unlock()
	g := r.slot(id)
	if g.done || n == 0 {
		return nil
	}
	if g.seen != n-1 {
		// Either everything arrived - nothing to repair - or more than one is
		// missing, which one parity packet cannot recover.
		g.done = true
		return nil
	}
	// The accumulator holds the exclusive-or of the packets that arrived,
	// each with its length in front. Folding the parity in leaves exactly the
	// one that did not.
	acc := g.acc
	for len(acc) < len(body) {
		acc = append(acc, 0)
	}
	g.scrap = g.scrap[:0]
	for i := range acc {
		var c byte
		if i < len(body) {
			c = body[i]
		}
		g.scrap = append(g.scrap, acc[i]^c)
	}
	g.acc = acc
	g.done = true

	if len(g.scrap) < 2 {
		return nil
	}
	l := int(binary.BigEndian.Uint16(g.scrap[0:2]))
	if l <= 0 || l > len(g.scrap)-2 {
		return nil
	}
	return g.scrap[2 : 2+l]
}

func foldInto(acc *[]byte, body []byte) {
	need := 2 + len(body)
	for len(*acc) < need {
		*acc = append(*acc, 0)
	}
	a := *acc
	var l [2]byte
	binary.BigEndian.PutUint16(l[:], uint16(len(body)))
	a[0] ^= l[0]
	a[1] ^= l[1]
	for i, c := range body {
		a[2+i] ^= c
	}
}
