    cat > "$d/internal/carrier/kcp.go" <<'PINGIFY_GO_SOURCE_EOF' || return 1
package carrier

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"io"
	"net"
	"sync"
	"sync/atomic"
	"time"

	kcp "github.com/xtaci/kcp-go/v5"

	"pingify/internal/buf"
	"pingify/internal/config"
	"pingify/internal/logging"
)

// KCP: the stream carrier on KCP sessions instead of TCP connections.
//
// Everything above the connection is TCP MUX unchanged - the slots, the hello
// that names one, two bytes of length in front of every frame - and the one
// thing that differs is what a connection is. Here it is a session of
// xtaci/kcp-go: reliable and ordered like TCP, but with a retransmit timer of
// its own running over UDP. A packet the path loses is repaired once, by KCP,
// rather than by a TCP stack inside the tunnel and another one outside it.
//
// What it needs from the path is UDP in both directions, and that is not a
// given. Earlier, on this same pair of servers, a UDP flow died after its
// sixth packet (see udp.go). Measured again on 2026-09-16 it did not: forty
// of forty on each of three flows, at a hundred bytes and at 1350. So this
// is a transport for the days UDP passes, and exactly the one to fall back
// from on the days it does not.
const (
	// A UDP payload that fits a 1500 byte path with room for a tunnel or a
	// PPPoE header somewhere on the way. kcptun has used the same number for
	// years, which is most of the world's experience of KCP on real paths.
	kcpMTU = 1350

	// KCP's clock and window, measured on the real pair on 2026-09-16: a
	// 200 MB download from Frankfurt through the tunnel, one at a time and
	// four at once, with KCP's own clock at 20 ms unless it says 10.
	//
	//	window 1024          97 Mbit/s one     381 four
	//	window 2048         169               623
	//	window 4096         267               759
	//	window 4096, 10 ms  269               807
	//	window 8192         298               388
	//
	// A window is how many packets may be in flight on one connection, and
	// one stream rides one connection, so at eighty milliseconds of round trip
	// a thousand packets is a ceiling of about a hundred megabits whatever
	// the path can carry. At 4096 the single core of the Iran server was the
	// limit instead - no idle time left - and 8192 only spent memory it did
	// not have. Acknowledging every packet at once instead of once per tick
	// took four streams from 807 to 411 and started dropping, so it is off.
	kcpInterval = 10
	kcpWindow   = 4096

	// The least receive buffer a KCP socket gets, whatever the profile says.
	// The profiles' 256 KB suits a private link's queue; under a KCP transfer
	// it dropped six thousand packets in twelve seconds on the Iran server,
	// and eight megabytes dropped none.
	kcpRcvBufKB = 8192

	// The largest frame on a KCP connection, eight times TCP's.
	//
	// What a KCP connection costs is not the bytes but the writes. kcp-go
	// flushes on every one, and a flush walks the whole window of in-flight
	// segments under the session's lock - profiled on the sending server
	// during one download, seventy per cent of the process was that walk,
	// once per two kilobyte record. The path was not the limit: of 473,872
	// packets sent, 473,435 arrived. A record eight times the size is an
	// eighth of the flushes for the same bytes. Measured against each other,
	// run in turn, fifteen seconds each:
	//
	//	              one download   four at once   upload   iran memory
	//	2 KB records    256 Mbit/s     680            212      88 MB
	//	16 KB           297            795            198      71
	//
	// Time to first byte did not move (81 ms either way), because a record is
	// only as large as what the local socket had to give when it was read.
	// 32 KB was no better than 16, and the buffer pool has a size for 16.
	kcpFrame = buf.BigSize

	kcpGreetLen = 8
)

// Variables rather than constants only so a test does not wait half a minute
// for each of them.
var (
	// How long a session may hear nothing before it is taken for dead.
	//
	// kcp-go marks a session dead after twenty retransmissions and then tells
	// nobody: Read and Write simply wait for ever. On TCP it is the kernel's
	// user timeout that ends a connection the route has stopped carrying, and
	// this is that for KCP. It is safe to be this short because neither side
	// is ever quiet for long - the side that dials sends a keepalive on every
	// connection, and the side that waits answers each one.
	kcpIdleMin = 30 * time.Second

	// How long the side that dials waits for the far end's greeting.
	kcpGreetWait = streamDialWait
)

func newKCPCarrier(cfg *config.Config) (*streamCarrier, error) {
	data, parity := kcpShards(cfg.Tuning.FEC)
	greet, answer := kcpGreeting(cfg.Token)
	idle, greetWait := kcpIdle(cfg), kcpGreetWait

	var ln net.Listener
	if !cfg.Dials() {
		port := cfg.Transport.Port
		if cfg.Transport.ListenPort > 0 {
			port = cfg.Transport.ListenPort
		}
		l, err := kcp.ListenWithOptions(fmt.Sprintf("0.0.0.0:%d", port), nil, data, parity)
		if err != nil {
			return nil, fmt.Errorf("listen on udp/%d: %v", port, err)
		}
		kcpSocket(l, cfg, true)
		ln = &kcpListener{Listener: l, idle: idle}
	}

	c, err := newStreamCarrierOn(cfg, "kcp", tcpLenLen, ln)
	if err != nil {
		if ln != nil {
			_ = ln.Close()
		}
		return nil, err
	}
	c.frame = kcpFrame

	if !cfg.Dials() {
		// The answer to a keepalive is what lets the side that dials tell a
		// quiet tunnel from a dead one. See kcpIdleMin.
		c.echo = true
		c.accept = func(nc net.Conn) (net.Conn, framing, error) {
			var got [kcpGreetLen]byte
			if _, err := io.ReadFull(nc, got[:]); err != nil {
				return nil, nil, err
			}
			if !bytes.Equal(got[:], greet) {
				return nil, nil, fmt.Errorf("kcp: not our greeting")
			}
			if _, err := nc.Write(answer); err != nil {
				return nil, nil, err
			}
			return nc, lenFraming{}, nil
		}
		return c, nil
	}

	addr := net.JoinHostPort(cfg.DialHost(), fmt.Sprint(cfg.Transport.Port))
	var said atomic.Bool
	c.dial = func() (net.Conn, framing, error) {
		ua, err := net.ResolveUDPAddr("udp4", addr)
		if err != nil {
			return nil, nil, err
		}
		s, err := kcp.DialWithOptions(ua.String(), nil, data, parity)
		if err != nil {
			return nil, nil, err
		}
		kcpSocket(s, cfg, !said.Swap(true))
		kc := newKCPConn(s, idle)

		// UDP has no handshake, so a session "opens" whether or not anything
		// is there. Without an answer to wait for, a server that is down
		// would look like eight connected slots, the status would say up,
		// and nothing would back off. The greeting is that answer: the far
		// end has to know the token to give it.
		_ = kc.SetDeadline(time.Now().Add(greetWait))
		if _, err := kc.Write(greet); err != nil {
			_ = kc.Close()
			return nil, nil, err
		}
		var got [kcpGreetLen]byte
		if _, err := io.ReadFull(kc, got[:]); err != nil {
			_ = kc.Close()
			return nil, nil, fmt.Errorf("kcp to %s: no answer", addr)
		}
		if !bytes.Equal(got[:], answer) {
			_ = kc.Close()
			return nil, nil, fmt.Errorf("kcp to %s: the answer is not from this tunnel", addr)
		}
		_ = kc.SetDeadline(time.Time{})
		return kc, lenFraming{}, nil
	}
	logging.Info("carrier: dialling %s over kcp, %d connections",
		addr, cfg.Transport.Connections)
	return c, nil
}

// kcpGreeting is what each side says first, derived from the token so that
// both know it and nobody else does. It is not the authentication - every
// frame after it carries a tag - it is the proof that something is there.
func kcpGreeting(token string) (greet, answer []byte) {
	sum := sha256.Sum256([]byte("pingify kcp greeting v1\x00" + token))
	return sum[:kcpGreetLen], sum[kcpGreetLen : 2*kcpGreetLen]
}

// kcpShards is KCP's own forward error correction, from tuning.fec: one
// parity shard per that many data shards, or none. The carrier-level parity
// the datagram transports use is not applied to this one - see noParity.
func kcpShards(fec int) (data, parity int) {
	if fec <= 0 {
		return 0, 0
	}
	return fec, 1
}

func kcpIdle(cfg *config.Config) time.Duration {
	d := 3 * time.Duration(cfg.Transport.Keepalive) * time.Second
	if d < kcpIdleMin {
		d = kcpIdleMin
	}
	return d
}

// kcpSocket sizes the UDP socket under a session or a listener, past
// net.core.rmem_max where the process may (see sizeSocket). A session of a
// listener shares the listener's socket, so this is called on whichever of
// the two owns one. say is whether to log what the kernel gave: the side
// that dials opens a socket per connection and per redial, and one line
// about it is enough.
func kcpSocket(s interface {
	Control(func(net.PacketConn) error) error
}, cfg *config.Config, say bool) {
	rcv := cfg.Tuning.RcvBufKB
	if rcv < kcpRcvBufKB {
		rcv = kcpRcvBufKB
	}
	_ = s.Control(func(pc net.PacketConn) error {
		gotRcv, gotSnd, ok := sizeSocket(pc, rcv*1024, cfg.Tuning.SndBufKB*1024, cfg.Tuning.DSCP)
		if !ok || !say {
			return nil
		}
		logging.Info("carrier: socket buffers, %d KB in, %d KB out", gotRcv/1024, gotSnd/1024)
		if gotRcv < rcv*1024*9/10 {
			logging.Warn("carrier: asked the kernel for %d KB of receive buffer and got %d KB -"+
				" raise net.core.rmem_max, or kcp will lose packets before it sees them",
				rcv, gotRcv/1024)
		}
		return nil
	})
}

type kcpListener struct {
	*kcp.Listener
	idle time.Duration
}

func (l *kcpListener) Accept() (net.Conn, error) {
	s, err := l.AcceptKCP()
	if err != nil {
		return nil, err
	}
	return newKCPConn(s, l.idle), nil
}

// kcpConn is a session that knows when it last heard anything, and closes
// itself when that was too long ago.
type kcpConn struct {
	*kcp.UDPSession
	heard atomic.Int64 // unix nanoseconds
	done  chan struct{}
	once  sync.Once
}

// newKCPConn sets a session up the way kcptun's fastest mode does - nodelay
// on, fast resend after two duplicate acknowledgements, no congestion window
// - with the clock and window measured above.
func newKCPConn(s *kcp.UDPSession, idle time.Duration) *kcpConn {
	s.SetStreamMode(true)
	s.SetWriteDelay(false)
	s.SetNoDelay(1, kcpInterval, 2, 1)
	s.SetWindowSize(kcpWindow, kcpWindow)
	s.SetMtu(kcpMTU)
	s.SetACKNoDelay(false)

	c := &kcpConn{UDPSession: s, done: make(chan struct{})}
	c.heard.Store(time.Now().UnixNano())
	go c.watch(idle)
	return c
}

func (c *kcpConn) Read(b []byte) (int, error) {
	n, err := c.UDPSession.Read(b)
	if n > 0 {
		c.heard.Store(time.Now().UnixNano())
	}
	return n, err
}

func (c *kcpConn) Close() error {
	c.once.Do(func() { close(c.done) })
	return c.UDPSession.Close()
}

func (c *kcpConn) watch(idle time.Duration) {
	tk := time.NewTicker(idle / 4)
	defer tk.Stop()
	for {
		select {
		case <-c.done:
			return
		case <-tk.C:
			if time.Since(time.Unix(0, c.heard.Load())) > idle {
				logging.Debug("carrier: nothing from %s over kcp in %s; closing it",
					c.RemoteAddr(), idle)
				_ = c.Close()
				return
			}
		}
	}
}
