    cat > "$d/internal/kernel/kernel.go" <<'PINGIFY_GO_SOURCE_EOF' || return 1
// Package kernel is the tunnel this process does not carry.
//
// Every other transport here moves the bytes itself: the core reads the
// device, seals each packet, puts it on a socket, and the far end undoes that.
// GRE FOU does none of it. The kernel holds a GRE device whose packets are
// wrapped in UDP - Linux's own FOU encapsulation - and the bytes never leave
// kernel space at all. Measured on the Tehran to Frankfurt pair, one stream:
//
//	GRE FOU (this)   921 Mbit/s down, 809 up
//	GRE  (our own)   645                592
//	UDP  (our own)   622                608
//
// What that speed costs is everything this core does to a packet. There is no
// token on the wire, so nothing proves who sent a packet: a machine that can
// forge the far end's address and knows the port is inside the tunnel. There
// is no sequence number of ours, so the path's losses cannot be counted. And
// there is nothing to move a stream to another transport with, so a tunnel on
// this one does not fail over.
//
// So this process still runs, and watches: it answers the status port and the
// health port with what the kernel's own counters say, which is what the
// manager draws and what the watchdog asks across the link. The device itself
// is made and unmade by the manager, next to the firewall rules and the
// offload setting that go with it - see parts/26-grefou.sh.
package kernel

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
	"time"

	"pingify/internal/config"
	"pingify/internal/logging"
)

type Link struct {
	dev  string
	up   atomic.Bool
	done chan struct{}
}

func New(cfg *config.Config) (*Link, error) {
	dev := cfg.TUN.Name
	if dev == "" {
		return nil, fmt.Errorf("tun.name is the kernel device this tunnel runs on, and it is empty")
	}
	l := &Link{dev: dev, done: make(chan struct{})}
	if !l.exists() {
		return nil, fmt.Errorf("%s does not exist: the manager brings the link up before this starts", dev)
	}
	mine, theirs := cfg.Mine()
	logging.Info("core: the kernel carries this tunnel on %s (%s to %s); this process only watches it",
		dev, addrOnly(mine), addrOnly(theirs))
	return l, nil
}

func addrOnly(s string) string {
	if i := strings.IndexByte(s, '/'); i >= 0 {
		return s[:i]
	}
	return s
}

// Watch keeps the device's state fresh until the tunnel stops. Nothing else
// in this process touches the wire.
func (l *Link) Watch() {
	tk := time.NewTicker(2 * time.Second)
	defer tk.Stop()
	for {
		l.up.Store(l.carrying())
		select {
		case <-l.done:
			return
		case <-tk.C:
		}
	}
}

func (l *Link) Close() error {
	select {
	case <-l.done:
	default:
		close(l.done)
	}
	return nil
}

func (l *Link) exists() bool {
	_, err := os.Stat("/sys/class/net/" + l.dev)
	return err == nil
}

// carrying is whether the device is up. A GRE device has no carrier to lose -
// there is no handshake and no peer state - so what can be asked is whether
// the device is there and administratively up.
func (l *Link) carrying() bool {
	if !l.exists() {
		return false
	}
	// IFF_UP, from the device's own flags. A GRE device has no operational
	// state worth reading: there is no handshake and no peer state, so the
	// kernel reports it as unknown whatever the far end is doing.
	const iffUp = 1
	return l.num("flags")&iffUp != 0
}

func (l *Link) stat(name string) uint64 { return l.num("statistics/" + name) }

// num reads one number out of the device's sysfs. A file that has gone - the
// device deleted under us - reads as zero rather than as an error nobody can
// act on.
func (l *Link) num(name string) uint64 {
	b, err := os.ReadFile("/sys/class/net/" + l.dev + "/" + name)
	if err != nil {
		return 0
	}
	s := strings.TrimSpace(string(b))
	if strings.HasPrefix(s, "0x") {
		n, err := strconv.ParseUint(s[2:], 16, 64)
		if err != nil {
			return 0
		}
		return n
	}
	n, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func (l *Link) Up() bool { return l.up.Load() }

// Counters are the device's, not ours. bad, replay and errs have no meaning
// without a record layer of our own, and are reported as zero rather than as
// numbers that look like something they are not.
func (l *Link) Counters() (rx, tx, bad, replay, errs uint64) {
	return l.stat("rx_bytes"), l.stat("tx_bytes"), 0, 0, l.stat("tx_errors")
}

// Lost is what the path took, and nothing here can see it: counting it needs
// a sequence number in every packet, which is the record layer this transport
// does without.
func (l *Link) Lost() (missing, late, gaps uint64) { return 0, 0, 0 }

func (l *Link) Dropped() uint64 { return l.stat("rx_dropped") + l.stat("tx_dropped") }

func (l *Link) Packets() (toWire, toDevice uint64) {
	return l.stat("tx_packets"), l.stat("rx_packets")
}

func (l *Link) String() string {
	toWire, toDevice := l.Packets()
	return fmt.Sprintf("kernel link %s: %d packets out, %d in, %d dropped",
		l.dev, toWire, toDevice, l.Dropped())
}
